class Attribute {
  final AttributeType? type;
  final List<AttributeValue>? values;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const Attribute._({this.type, this.values, this.asn1});

  const Attribute({AttributeType? type, List<AttributeValue>? values})
    : this._(type: type, values: values, asn1: null);

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (type != null) {
      children.add(asn1EncodeRaw(0x6, Uint8List.fromList(type!.codeUnits)));
    }
    if (values != null) {
      final items = <Uint8List>[];
      for (final v in values!) {
        items.add(asn1EncodeRaw(0x4, v));
      }
      children.add(asn1EncodeConstructed(0x31, items));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory Attribute.fromAsn1(Asn1Node node) {
    AttributeType? type;
    List<AttributeValue>? values;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x6);
    if (found >= 0) {
      final child = node.children[found];
      type = String.fromCharCodes(child.value);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x31);
    if (found >= 0) {
      final child = node.children[found];
      final items = <AttributeValue>[];
      for (final n in child.children) {
        items.add(n.value);
      }
      values = items;
      childIdx = found + 1;
    }
    return Attribute._(
      type: type,
      values: values,
      asn1: node, // Store original node
    );
  }

  static Attribute decode(dynamic data) {
    if (data is Asn1Node) {
      return Attribute.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return Attribute.fromAsn1(node);
      }
    }
    return Attribute();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('Attribute(');
    final typeVal = type;
    if (typeVal != null) {
      buffer.writeln('  type: ${typeVal.toString().replaceAll("\n", "\n  ")},');
    }
    final valuesVal = values;
    if (valuesVal != null) {
      buffer.writeln(
        '  values: [${valuesVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class AttributeTypeAndValue {
  final AttributeType? type;
  final AttributeValue? value;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const AttributeTypeAndValue._({this.type, this.value, this.asn1});

  const AttributeTypeAndValue({AttributeType? type, AttributeValue? value})
    : this._(type: type, value: value, asn1: null);

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (type != null) {
      children.add(asn1EncodeRaw(0x6, Uint8List.fromList(type!.codeUnits)));
    }
    if (value != null) {
      children.add(asn1EncodeRaw(0x4, value!));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory AttributeTypeAndValue.fromAsn1(Asn1Node node) {
    AttributeType? type;
    AttributeValue? value;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x6);
    if (found >= 0) {
      final child = node.children[found];
      type = String.fromCharCodes(child.value);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x4);
    if (found >= 0) {
      final child = node.children[found];
      value = child.value;
      childIdx = found + 1;
    }
    return AttributeTypeAndValue._(
      type: type,
      value: value,
      asn1: node, // Store original node
    );
  }

  static AttributeTypeAndValue decode(dynamic data) {
    if (data is Asn1Node) {
      return AttributeTypeAndValue.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return AttributeTypeAndValue.fromAsn1(node);
      }
    }
    return AttributeTypeAndValue();
  }

  @override
  String toString() {
    var t = type ?? 'unknown';
    if (t == "\x55\x04\x03") {
      t = "CN";
    } else if (t == "\x55\x04\x06") {
      t = "C";
    } else if (t == "\x55\x04\x0A") {
      t = "O";
    } else if (t == "\x55\x04\x0B") {
      t = "OU";
    } else if (t == "\x55\x04\x07") {
      t = "L";
    } else if (t == "\x55\x04\x08") {
      t = "ST";
    }
    var v = 'null';
    final val = value;
    if (val != null) {
      try {
        v = utf8.decode(val);
      } catch (_) {
        v = val.map((b) => b.toRadixString(16).padLeft(2, '0')).join('');
      }
    }
    return '$t=$v';
  }
}

