class Name {
  final RDNSequence? rdnSequence;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const Name._({this.rdnSequence, this.asn1});

  const Name({RDNSequence? rdnSequence})
    : this._(rdnSequence: rdnSequence, asn1: null);

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (rdnSequence != null) {
      final items = <Uint8List>[];
      for (final v in rdnSequence!) {
        items.add(
          asn1EncodeConstructed(0x31, [
            for (final v1 in v) v1.encode(tag: 0x30),
          ]),
        );
      }
      children.add(asn1EncodeConstructed(0x30, items));
    }
    if (tag != null) {
      return asn1EncodeConstructed(tag, children);
    }
    return children.isNotEmpty ? children.first : Uint8List(0);
  }

  factory Name.fromAsn1(Asn1Node node) {
    RDNSequence? rdnSequence;
    // CHOICE: check node's tag directly
    switch (node.tag) {
      case 0x30:
        final items = <List<AttributeTypeAndValue>>[];
        for (final n in node.children) {
          items.add(
            n.children.map((sn0) => AttributeTypeAndValue.decode(sn0)).toList(),
          );
        }
        rdnSequence = items;
        break;
    }
    return Name._(
      rdnSequence: rdnSequence,
      asn1: node, // Store original node
    );
  }

  static Name decode(dynamic data) {
    if (data is Asn1Node) {
      return Name.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return Name.fromAsn1(node);
      }
    }
    return Name();
  }

  @override
  String toString() {
    final rdnSequenceVal = rdnSequence;
    if (rdnSequenceVal == null) {
      return 'Name()';
    }
    return rdnSequenceVal
        .map((item) => item.map((e) => e.toString()).join(" + "))
        .join(", ");
  }
}

