class Certificate {
  final TBSCertificate? tbsCertificate;
  final AlgorithmIdentifier? signatureAlgorithm;
  final int? signature;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const Certificate._({
    this.tbsCertificate,
    this.signatureAlgorithm,
    this.signature,
    this.asn1,
  });

  const Certificate({
    TBSCertificate? tbsCertificate,
    AlgorithmIdentifier? signatureAlgorithm,
    int? signature,
  }) : this._(
         tbsCertificate: tbsCertificate,
         signatureAlgorithm: signatureAlgorithm,
         signature: signature,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (tbsCertificate != null) {
      children.add(tbsCertificate!.encode(tag: 0x30));
    }
    if (signatureAlgorithm != null) {
      children.add(signatureAlgorithm!.encode(tag: 0x30));
    }
    if (signature != null) {
      children.add(asn1EncodeRaw(0x3, asn1EncodeBits(signature!)));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory Certificate.fromAsn1(Asn1Node node) {
    TBSCertificate? tbsCertificate;
    AlgorithmIdentifier? signatureAlgorithm;
    int? signature;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x30);
    if (found >= 0) {
      final child = node.children[found];
      tbsCertificate = TBSCertificate.decode(child);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x30);
    if (found >= 0) {
      final child = node.children[found];
      signatureAlgorithm = AlgorithmIdentifier.decode(child);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x3);
    if (found >= 0) {
      final child = node.children[found];
      signature = asn1DecodeBits(child.value);
      childIdx = found + 1;
    }
    return Certificate._(
      tbsCertificate: tbsCertificate,
      signatureAlgorithm: signatureAlgorithm,
      signature: signature,
      asn1: node, // Store original node
    );
  }

  static Certificate decode(dynamic data) {
    if (data is Asn1Node) {
      return Certificate.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return Certificate.fromAsn1(node);
      }
    }
    return Certificate();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('Certificate(');
    final tbsCertificateVal = tbsCertificate;
    if (tbsCertificateVal != null) {
      buffer.writeln(
        '  tbsCertificate: ${tbsCertificateVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final signatureAlgorithmVal = signatureAlgorithm;
    if (signatureAlgorithmVal != null) {
      buffer.writeln(
        '  signatureAlgorithm: ${signatureAlgorithmVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final signatureVal = signature;
    if (signatureVal != null) {
      buffer.writeln(
        '  signature: ${signatureVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class TBSCertificate {
  final Version? version;
  final CertificateSerialNumber? serialNumber;
  final AlgorithmIdentifier? signature;
  final Name? issuer;
  final Validity? validity;
  final Name? subject;
  final SubjectPublicKeyInfo? subjectPublicKeyInfo;
  final int? issuerUniqueID;
  final int? subjectUniqueID;
  final Extensions? extensions;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const TBSCertificate._({
    this.version,
    this.serialNumber,
    this.signature,
    this.issuer,
    this.validity,
    this.subject,
    this.subjectPublicKeyInfo,
    this.issuerUniqueID,
    this.subjectUniqueID,
    this.extensions,
    this.asn1,
  });

  const TBSCertificate({
    Version? version,
    CertificateSerialNumber? serialNumber,
    AlgorithmIdentifier? signature,
    Name? issuer,
    Validity? validity,
    Name? subject,
    SubjectPublicKeyInfo? subjectPublicKeyInfo,
    int? issuerUniqueID,
    int? subjectUniqueID,
    Extensions? extensions,
  }) : this._(
         version: version,
         serialNumber: serialNumber,
         signature: signature,
         issuer: issuer,
         validity: validity,
         subject: subject,
         subjectPublicKeyInfo: subjectPublicKeyInfo,
         issuerUniqueID: issuerUniqueID,
         subjectUniqueID: subjectUniqueID,
         extensions: extensions,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (version != null) {
      children.add(
        asn1EncodeConstructed(0xA0, [
          asn1EncodeRaw(0x2, asn1EncodeInt(version!.value)),
        ]),
      );
    }
    if (serialNumber != null) {
      children.add(asn1EncodeRaw(0x2, serialNumber!));
    }
    if (signature != null) {
      children.add(signature!.encode(tag: 0x30));
    }
    if (issuer != null) {
      children.add(issuer!.encode());
    }
    if (validity != null) {
      children.add(validity!.encode(tag: 0x30));
    }
    if (subject != null) {
      children.add(subject!.encode());
    }
    if (subjectPublicKeyInfo != null) {
      children.add(subjectPublicKeyInfo!.encode(tag: 0x30));
    }
    if (issuerUniqueID != null) {
      children.add(asn1EncodeRaw(0x81, asn1EncodeBits(issuerUniqueID!)));
    }
    if (subjectUniqueID != null) {
      children.add(asn1EncodeRaw(0x82, asn1EncodeBits(subjectUniqueID!)));
    }
    if (extensions != null) {
      final items = <Uint8List>[];
      for (final v in extensions!) {
        items.add(v.encode(tag: 0x30));
      }
      children.add(
        asn1EncodeConstructed(0xA3, [asn1EncodeConstructed(0x30, items)]),
      );
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory TBSCertificate.fromAsn1(Asn1Node node) {
    Version? version;
    CertificateSerialNumber? serialNumber;
    AlgorithmIdentifier? signature;
    Name? issuer;
    Validity? validity;
    Name? subject;
    SubjectPublicKeyInfo? subjectPublicKeyInfo;
    int? issuerUniqueID;
    int? subjectUniqueID;
    Extensions? extensions;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0xA0);
    if (found >= 0) {
      final child = node.children[found];
      version = VersionExt.fromValue(asn1DecodeInt(asn1Explicit(child).value));
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x2);
    if (found >= 0) {
      final child = node.children[found];
      serialNumber = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x30);
    if (found >= 0) {
      final child = node.children[found];
      signature = AlgorithmIdentifier.decode(child);
      childIdx = found + 1;
    }
    if (childIdx < node.children.length) {
      final child = node.children[childIdx];
      issuer = Name.decode(child);
      childIdx++;
    }
    found = asn1SeekTag(node.children, childIdx, 0x30);
    if (found >= 0) {
      final child = node.children[found];
      validity = Validity.decode(child);
      childIdx = found + 1;
    }
    if (childIdx < node.children.length) {
      final child = node.children[childIdx];
      subject = Name.decode(child);
      childIdx++;
    }
    found = asn1SeekTag(node.children, childIdx, 0x30);
    if (found >= 0) {
      final child = node.children[found];
      subjectPublicKeyInfo = SubjectPublicKeyInfo.decode(child);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x81);
    if (found >= 0) {
      final child = node.children[found];
      issuerUniqueID = asn1DecodeBits(child.value);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x82);
    if (found >= 0) {
      final child = node.children[found];
      subjectUniqueID = asn1DecodeBits(child.value);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA3);
    if (found >= 0) {
      final child = node.children[found];
      final items = <Extension>[];
      for (final n in asn1Explicit(child).children) {
        items.add(Extension.decode(n));
      }
      extensions = items;
      childIdx = found + 1;
    }
    return TBSCertificate._(
      version: version,
      serialNumber: serialNumber,
      signature: signature,
      issuer: issuer,
      validity: validity,
      subject: subject,
      subjectPublicKeyInfo: subjectPublicKeyInfo,
      issuerUniqueID: issuerUniqueID,
      subjectUniqueID: subjectUniqueID,
      extensions: extensions,
      asn1: node, // Store original node
    );
  }

  static TBSCertificate decode(dynamic data) {
    if (data is Asn1Node) {
      return TBSCertificate.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return TBSCertificate.fromAsn1(node);
      }
    }
    return TBSCertificate();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('TBSCertificate(');
    final versionVal = version;
    if (versionVal != null) {
      buffer.writeln(
        '  version: ${versionVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final serialNumberVal = serialNumber;
    if (serialNumberVal != null) {
      buffer.writeln('  serialNumber: ${asn1Hex(serialNumberVal)},');
    }
    final signatureVal = signature;
    if (signatureVal != null) {
