class AlgorithmIdentifier {
  final Uint8List? algorithm;
  final Uint8List? parameters;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const AlgorithmIdentifier._({this.algorithm, this.parameters, this.asn1});

  const AlgorithmIdentifier({Uint8List? algorithm, Uint8List? parameters})
    : this._(algorithm: algorithm, parameters: parameters, asn1: null);

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (algorithm != null) {
      children.add(asn1EncodeRaw(0x6, algorithm!));
    }
    if (parameters != null) {
      children.add(asn1EncodeRaw(0x4, parameters!));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory AlgorithmIdentifier.fromAsn1(Asn1Node node) {
    Uint8List? algorithm;
    Uint8List? parameters;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x6);
    if (found >= 0) {
      final child = node.children[found];
      algorithm = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x4);
    if (found >= 0) {
      final child = node.children[found];
      parameters = child.value;
      childIdx = found + 1;
    }
    return AlgorithmIdentifier._(
      algorithm: algorithm,
      parameters: parameters,
      asn1: node, // Store original node
    );
  }

  static AlgorithmIdentifier decode(dynamic data) {
    if (data is Asn1Node) {
      return AlgorithmIdentifier.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return AlgorithmIdentifier.fromAsn1(node);
      }
    }
    return AlgorithmIdentifier();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('AlgorithmIdentifier(');
    final algorithmVal = algorithm;
    if (algorithmVal != null) {
      buffer.writeln('  algorithm: ${asn1Hex(algorithmVal)},');
    }
    final parametersVal = parameters;
    if (parametersVal != null) {
      buffer.writeln('  parameters: ${asn1Hex(parametersVal)},');
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class ORAddress {
  final BuiltInStandardAttributes? built_in_standard_attributes;
  final BuiltInDomainDefinedAttributes? built_in_domain_defined_attributes;
  final ExtensionAttributes? extension_attributes;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const ORAddress._({
    this.built_in_standard_attributes,
    this.built_in_domain_defined_attributes,
    this.extension_attributes,
    this.asn1,
  });

  const ORAddress({
    BuiltInStandardAttributes? built_in_standard_attributes,
    BuiltInDomainDefinedAttributes? built_in_domain_defined_attributes,
    ExtensionAttributes? extension_attributes,
  }) : this._(
         built_in_standard_attributes: built_in_standard_attributes,
         built_in_domain_defined_attributes: built_in_domain_defined_attributes,
         extension_attributes: extension_attributes,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (built_in_standard_attributes != null) {
      children.add(built_in_standard_attributes!.encode(tag: 0x30));
    }
    if (built_in_domain_defined_attributes != null) {
      final items = <Uint8List>[];
      for (final v in built_in_domain_defined_attributes!) {
        items.add(v.encode(tag: 0x30));
      }
      children.add(asn1EncodeConstructed(0x30, items));
    }
    if (extension_attributes != null) {
      final items = <Uint8List>[];
      for (final v in extension_attributes!) {
        items.add(v.encode(tag: 0x30));
      }
      children.add(asn1EncodeConstructed(0x31, items));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory ORAddress.fromAsn1(Asn1Node node) {
    BuiltInStandardAttributes? built_in_standard_attributes;
    BuiltInDomainDefinedAttributes? built_in_domain_defined_attributes;
    ExtensionAttributes? extension_attributes;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x30);
    if (found >= 0) {
      final child = node.children[found];
      built_in_standard_attributes = BuiltInStandardAttributes.decode(child);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x30);
    if (found >= 0) {
      final child = node.children[found];
      final items = <BuiltInDomainDefinedAttribute>[];
      for (final n in child.children) {
        items.add(BuiltInDomainDefinedAttribute.decode(n));
      }
      built_in_domain_defined_attributes = items;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x31);
    if (found >= 0) {
      final child = node.children[found];
      final items = <ExtensionAttribute>[];
      for (final n in child.children) {
        items.add(ExtensionAttribute.decode(n));
      }
      extension_attributes = items;
      childIdx = found + 1;
    }
    return ORAddress._(
      built_in_standard_attributes: built_in_standard_attributes,
      built_in_domain_defined_attributes: built_in_domain_defined_attributes,
      extension_attributes: extension_attributes,
      asn1: node, // Store original node
    );
  }

  static ORAddress decode(dynamic data) {
    if (data is Asn1Node) {
      return ORAddress.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return ORAddress.fromAsn1(node);
      }
    }
    return ORAddress();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('ORAddress(');
    final built_in_standard_attributesVal = built_in_standard_attributes;
    if (built_in_standard_attributesVal != null) {
      buffer.writeln(
        '  built_in_standard_attributes: ${built_in_standard_attributesVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final built_in_domain_defined_attributesVal =
        built_in_domain_defined_attributes;
    if (built_in_domain_defined_attributesVal != null) {
      buffer.writeln(
        '  built_in_domain_defined_attributes: [${built_in_domain_defined_attributesVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    final extension_attributesVal = extension_attributes;
    if (extension_attributesVal != null) {
      buffer.writeln(
        '  extension_attributes: [${extension_attributesVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

