         numeric_user_identifier: numeric_user_identifier,
         personal_name: personal_name,
         organizational_unit_names: organizational_unit_names,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (country_name != null) {
      children.add(country_name!.encode(tag: 0x61));
    }
    if (administration_domain_name != null) {
      children.add(administration_domain_name!.encode(tag: 0x62));
    }
    if (network_address != null) {
      children.add(
        asn1EncodeRaw(0x80, Uint8List.fromList(network_address!.codeUnits)),
      );
    }
    if (terminal_identifier != null) {
      children.add(
        asn1EncodeRaw(0x81, Uint8List.fromList(terminal_identifier!.codeUnits)),
      );
    }
    if (private_domain_name != null) {
      children.add(
        asn1EncodeConstructed(0xA2, [private_domain_name!.encode()]),
      );
    }
    if (organization_name != null) {
      children.add(
        asn1EncodeRaw(0x83, Uint8List.fromList(organization_name!.codeUnits)),
      );
    }
    if (numeric_user_identifier != null) {
      children.add(
        asn1EncodeRaw(
          0x84,
          Uint8List.fromList(numeric_user_identifier!.codeUnits),
        ),
      );
    }
    if (personal_name != null) {
      children.add(personal_name!.encode(tag: 0xA5));
    }
    if (organizational_unit_names != null) {
      final items = <Uint8List>[];
      for (final v in organizational_unit_names!) {
        items.add(asn1EncodeRaw(0x13, Uint8List.fromList(v.codeUnits)));
      }
      children.add(asn1EncodeConstructed(0xA6, items));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
