    OrganizationName? organization_name;
    NumericUserIdentifier? numeric_user_identifier;
    PersonalName? personal_name;
    OrganizationalUnitNames? organizational_unit_names;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x61);
    if (found >= 0) {
