      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x81);
    if (found >= 0) {
      final child = node.children[found];
      terminal_identifier = String.fromCharCodes(child.value);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA2);
    if (found >= 0) {
      final child = node.children[found];
      private_domain_name = PrivateDomainName.decode(asn1Explicit(child));
      childIdx = found + 1;
