    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory BuiltInDomainDefinedAttribute.fromAsn1(Asn1Node node) {
    String? type;
    String? value;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x13);
    if (found >= 0) {
      final child = node.children[found];
      type = String.fromCharCodes(child.value);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x13);
    if (found >= 0) {
      final child = node.children[found];
      value = String.fromCharCodes(child.value);
      childIdx = found + 1;
    }
    return BuiltInDomainDefinedAttribute._(
      type: type,
      value: value,
      asn1: node, // Store original node
    );
  }

  static BuiltInDomainDefinedAttribute decode(dynamic data) {
    if (data is Asn1Node) {
      return BuiltInDomainDefinedAttribute.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return BuiltInDomainDefinedAttribute.fromAsn1(node);
      }
    }
    return BuiltInDomainDefinedAttribute();
  }

  @override
  String toString() {
    var t = type ?? 'unknown';
    if (t == "\x55\x04\x03") {
      t = "CN";
    } else if (t == "\x55\x04\x06") {
      t = "C";
    } else if (t == "\x55\x04\x0A") {
      t = "O";
    } else if (t == "\x55\x04\x0B") {
      t = "OU";
    } else if (t == "\x55\x04\x07") {
      t = "L";
    } else if (t == "\x55\x04\x08") {
      t = "ST";
    }
    var v = 'null';
    final val = value;
    if (val != null) {
      v = val;
    }
    return '$t=$v';
  }
}

class ExtensionAttribute {
  final int? extension_attribute_type;
  final Uint8List? extension_attribute_value;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const ExtensionAttribute._({
    this.extension_attribute_type,
    this.extension_attribute_value,
    this.asn1,
  });

  const ExtensionAttribute({
    int? extension_attribute_type,
    Uint8List? extension_attribute_value,
  }) : this._(
         extension_attribute_type: extension_attribute_type,
         extension_attribute_value: extension_attribute_value,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (extension_attribute_type != null) {
      children.add(
        asn1EncodeRaw(0x80, asn1EncodeInt(extension_attribute_type!)),
      );
    }
    if (extension_attribute_value != null) {
      children.add(
        asn1EncodeConstructed(0xA1, [
          asn1EncodeRaw(0x4, extension_attribute_value!),
        ]),
      );
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory ExtensionAttribute.fromAsn1(Asn1Node node) {
    int? extension_attribute_type;
    Uint8List? extension_attribute_value;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x80);
    if (found >= 0) {
      final child = node.children[found];
      extension_attribute_type = asn1DecodeInt(child.value);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA1);
    if (found >= 0) {
      final child = node.children[found];
      extension_attribute_value = asn1Explicit(child).value;
      childIdx = found + 1;
    }
    return ExtensionAttribute._(
      extension_attribute_type: extension_attribute_type,
      extension_attribute_value: extension_attribute_value,
      asn1: node, // Store original node
    );
  }

  static ExtensionAttribute decode(dynamic data) {
    if (data is Asn1Node) {
      return ExtensionAttribute.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return ExtensionAttribute.fromAsn1(node);
      }
    }
    return ExtensionAttribute();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('ExtensionAttribute(');
    final extension_attribute_typeVal = extension_attribute_type;
    if (extension_attribute_typeVal != null) {
      buffer.writeln(
        '  extension_attribute_type: ${extension_attribute_typeVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final extension_attribute_valueVal = extension_attribute_value;
    if (extension_attribute_valueVal != null) {
      buffer.writeln(
        '  extension_attribute_value: ${asn1Hex(extension_attribute_valueVal)},',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

