class PresentationAddress {
  final Uint8List? pSelector;
  final Uint8List? sSelector;
  final Uint8List? tSelector;
  final List<Uint8List>? nAddresses;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const PresentationAddress._({
    this.pSelector,
    this.sSelector,
    this.tSelector,
    this.nAddresses,
    this.asn1,
  });

  const PresentationAddress({
    Uint8List? pSelector,
    Uint8List? sSelector,
    Uint8List? tSelector,
    List<Uint8List>? nAddresses,
  }) : this._(
         pSelector: pSelector,
         sSelector: sSelector,
         tSelector: tSelector,
         nAddresses: nAddresses,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (pSelector != null) {
      children.add(
        asn1EncodeConstructed(0xA0, [asn1EncodeRaw(0x4, pSelector!)]),
      );
    }
    if (sSelector != null) {
      children.add(
        asn1EncodeConstructed(0xA1, [asn1EncodeRaw(0x4, sSelector!)]),
      );
    }
    if (tSelector != null) {
      children.add(
        asn1EncodeConstructed(0xA2, [asn1EncodeRaw(0x4, tSelector!)]),
      );
    }
    if (nAddresses != null) {
      final items = <Uint8List>[];
      for (final v in nAddresses!) {
        items.add(asn1EncodeRaw(0x4, v));
      }
      children.add(
        asn1EncodeConstructed(0xA3, [asn1EncodeConstructed(0x31, items)]),
      );
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory PresentationAddress.fromAsn1(Asn1Node node) {
    Uint8List? pSelector;
    Uint8List? sSelector;
    Uint8List? tSelector;
    List<Uint8List>? nAddresses;
    int childIdx = 0;
