    found = asn1SeekTag(node.children, childIdx, 0xA0);
    if (found >= 0) {
      final child = node.children[found];
      pSelector = asn1Explicit(child).value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA1);
    if (found >= 0) {
      final child = node.children[found];
      sSelector = asn1Explicit(child).value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA2);
    if (found >= 0) {
      final child = node.children[found];
      tSelector = asn1Explicit(child).value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA3);
    if (found >= 0) {
      final child = node.children[found];
      final items = <Uint8List>[];
      for (final n in asn1Explicit(child).children) {
        items.add(n.value);
      }
      nAddresses = items;
      childIdx = found + 1;
    }
    return PresentationAddress._(
      pSelector: pSelector,
      sSelector: sSelector,
      tSelector: tSelector,
      nAddresses: nAddresses,
      asn1: node, // Store original node
    );
  }

  static PresentationAddress decode(dynamic data) {
    if (data is Asn1Node) {
      return PresentationAddress.fromAsn1(data);
    }
