class TeletexDomainDefinedAttribute {
  final String? type;
  final String? value;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const TeletexDomainDefinedAttribute._({this.type, this.value, this.asn1});

  const TeletexDomainDefinedAttribute({String? type, String? value})
    : this._(type: type, value: value, asn1: null);

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (type != null) {
      children.add(asn1EncodeRaw(0x14, Uint8List.fromList(type!.codeUnits)));
    }
    if (value != null) {
      children.add(asn1EncodeRaw(0x14, Uint8List.fromList(value!.codeUnits)));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory TeletexDomainDefinedAttribute.fromAsn1(Asn1Node node) {
    String? type;
    String? value;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x14);
    if (found >= 0) {
      final child = node.children[found];
      type = String.fromCharCodes(child.value);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x14);
    if (found >= 0) {
      final child = node.children[found];
      value = String.fromCharCodes(child.value);
      childIdx = found + 1;
    }
    return TeletexDomainDefinedAttribute._(
      type: type,
      value: value,
      asn1: node, // Store original node
    );
  }

  static TeletexDomainDefinedAttribute decode(dynamic data) {
    if (data is Asn1Node) {
      return TeletexDomainDefinedAttribute.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return TeletexDomainDefinedAttribute.fromAsn1(node);
      }
    }
    return TeletexDomainDefinedAttribute();
  }

  @override
  String toString() {
    var t = type ?? 'unknown';
    if (t == "\x55\x04\x03") {
      t = "CN";
    } else if (t == "\x55\x04\x06") {
      t = "C";
    } else if (t == "\x55\x04\x0A") {
      t = "O";
    } else if (t == "\x55\x04\x0B") {
      t = "OU";
    } else if (t == "\x55\x04\x07") {
      t = "L";
    } else if (t == "\x55\x04\x08") {
      t = "ST";
    }
    var v = 'null';
    final val = value;
    if (val != null) {
      v = val;
    }
    return '$t=$v';
  }
}

class AuthorityKeyIdentifier {
  final KeyIdentifier? keyIdentifier;
  final GeneralNames? authorityCertIssuer;
  final CertificateSerialNumber? authorityCertSerialNumber;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const AuthorityKeyIdentifier._({
    this.keyIdentifier,
    this.authorityCertIssuer,
    this.authorityCertSerialNumber,
    this.asn1,
  });

  const AuthorityKeyIdentifier({
    KeyIdentifier? keyIdentifier,
    GeneralNames? authorityCertIssuer,
    CertificateSerialNumber? authorityCertSerialNumber,
  }) : this._(
         keyIdentifier: keyIdentifier,
         authorityCertIssuer: authorityCertIssuer,
         authorityCertSerialNumber: authorityCertSerialNumber,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (keyIdentifier != null) {
      children.add(asn1EncodeRaw(0x80, keyIdentifier!));
    }
    if (authorityCertIssuer != null) {
      final items = <Uint8List>[];
      for (final v in authorityCertIssuer!) {
        items.add(v.encode());
      }
      children.add(asn1EncodeConstructed(0xA1, items));
    }
    if (authorityCertSerialNumber != null) {
      children.add(asn1EncodeRaw(0x82, authorityCertSerialNumber!));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory AuthorityKeyIdentifier.fromAsn1(Asn1Node node) {
    KeyIdentifier? keyIdentifier;
    GeneralNames? authorityCertIssuer;
    CertificateSerialNumber? authorityCertSerialNumber;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x80);
    if (found >= 0) {
      final child = node.children[found];
      keyIdentifier = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA1);
    if (found >= 0) {
      final child = node.children[found];
      final items = <GeneralName>[];
      for (final n in child.children) {
        items.add(GeneralName.decode(n));
      }
      authorityCertIssuer = items;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x82);
    if (found >= 0) {
      final child = node.children[found];
      authorityCertSerialNumber = child.value;
      childIdx = found + 1;
    }
    return AuthorityKeyIdentifier._(
      keyIdentifier: keyIdentifier,
      authorityCertIssuer: authorityCertIssuer,
      authorityCertSerialNumber: authorityCertSerialNumber,
      asn1: node, // Store original node
    );
  }

  static AuthorityKeyIdentifier decode(dynamic data) {
    if (data is Asn1Node) {
      return AuthorityKeyIdentifier.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return AuthorityKeyIdentifier.fromAsn1(node);
      }
    }
    return AuthorityKeyIdentifier();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('AuthorityKeyIdentifier(');
    final keyIdentifierVal = keyIdentifier;
    if (keyIdentifierVal != null) {
      buffer.writeln('  keyIdentifier: ${asn1Hex(keyIdentifierVal)},');
    }
    final authorityCertIssuerVal = authorityCertIssuer;
    if (authorityCertIssuerVal != null) {
      buffer.writeln(
        '  authorityCertIssuer: [${authorityCertIssuerVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    final authorityCertSerialNumberVal = authorityCertSerialNumber;
    if (authorityCertSerialNumberVal != null) {
      buffer.writeln(
        '  authorityCertSerialNumber: ${asn1Hex(authorityCertSerialNumberVal)},',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

