    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (noticeRef != null) {
      children.add(noticeRef!.encode(tag: 0x30));
    }
    if (explicitText != null) {
      children.add(explicitText!.encode());
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory UserNotice.fromAsn1(Asn1Node node) {
    NoticeReference? noticeRef;
    DisplayText? explicitText;
    int childIdx = 0;
