    found = asn1SeekTag(node.children, childIdx, 0x30);
    if (found >= 0) {
      final child = node.children[found];
      noticeRef = NoticeReference.decode(child);
      childIdx = found + 1;
    }
    if (childIdx < node.children.length) {
      final child = node.children[childIdx];
      explicitText = DisplayText.decode(child);
      childIdx++;
    }
    return UserNotice._(
      noticeRef: noticeRef,
      explicitText: explicitText,
      asn1: node, // Store original node
