    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (ia5String != null) {
      children.add(
        asn1EncodeRaw(0x16, Uint8List.fromList(ia5String!.codeUnits)),
      );
    }
    if (visibleString != null) {
      children.add(
        asn1EncodeRaw(0x1A, Uint8List.fromList(visibleString!.codeUnits)),
      );
    }
    if (bmpString != null) {
      children.add(
        asn1EncodeRaw(0x1E, Uint8List.fromList(bmpString!.codeUnits)),
      );
    }
    if (utf8String != null) {
      children.add(
        asn1EncodeRaw(0xC, Uint8List.fromList(utf8String!.codeUnits)),
      );
    }
    if (tag != null) {
      return asn1EncodeConstructed(tag, children);
    }
    return children.isNotEmpty ? children.first : Uint8List(0);
  }

  factory DisplayText.fromAsn1(Asn1Node node) {
    String? ia5String;
    String? visibleString;
    String? bmpString;
    String? utf8String;
    // CHOICE: check node's tag directly
    switch (node.tag) {
      case 0x16:
        ia5String = String.fromCharCodes(node.value);
        break;
      case 0x1A:
        visibleString = String.fromCharCodes(node.value);
        break;
      case 0x1E:
        bmpString = String.fromCharCodes(node.value);
        break;
      case 0xC:
        utf8String = String.fromCharCodes(node.value);
        break;
    }
    return DisplayText._(
      ia5String: ia5String,
      visibleString: visibleString,
      bmpString: bmpString,
      utf8String: utf8String,
      asn1: node, // Store original node
    );
  }

  static DisplayText decode(dynamic data) {
    if (data is Asn1Node) {
      return DisplayText.fromAsn1(data);
