    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return DisplayText.fromAsn1(node);
      }
    }
    return DisplayText();
  }

  @override
  String toString() {
    final ia5StringVal = ia5String;
    if (ia5StringVal != null) {
