class GeneralName {
  final AnotherName? otherName;
  final String? rfc822Name;
  final String? dNSName;
  final ORAddress? x400Address;
  final Name? directoryName;
  final EDIPartyName? ediPartyName;
  final String? uniformResourceIdentifier;
  final Uint8List? iPAddress;
  final Uint8List? registeredID;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const GeneralName._({
    this.otherName,
    this.rfc822Name,
    this.dNSName,
    this.x400Address,
    this.directoryName,
    this.ediPartyName,
    this.uniformResourceIdentifier,
    this.iPAddress,
    this.registeredID,
    this.asn1,
  });

  const GeneralName({
    AnotherName? otherName,
    String? rfc822Name,
    String? dNSName,
    ORAddress? x400Address,
    Name? directoryName,
    EDIPartyName? ediPartyName,
    String? uniformResourceIdentifier,
    Uint8List? iPAddress,
    Uint8List? registeredID,
  }) : this._(
         otherName: otherName,
         rfc822Name: rfc822Name,
         dNSName: dNSName,
         x400Address: x400Address,
         directoryName: directoryName,
         ediPartyName: ediPartyName,
         uniformResourceIdentifier: uniformResourceIdentifier,
         iPAddress: iPAddress,
         registeredID: registeredID,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (otherName != null) {
      children.add(otherName!.encode(tag: 0xA0));
    }
    if (rfc822Name != null) {
      children.add(
        asn1EncodeRaw(0x81, Uint8List.fromList(rfc822Name!.codeUnits)),
      );
    }
    if (dNSName != null) {
      children.add(asn1EncodeRaw(0x82, Uint8List.fromList(dNSName!.codeUnits)));
    }
    if (x400Address != null) {
      children.add(x400Address!.encode(tag: 0xA3));
    }
    if (directoryName != null) {
      children.add(asn1EncodeConstructed(0xA4, [directoryName!.encode()]));
    }
    if (ediPartyName != null) {
      children.add(ediPartyName!.encode(tag: 0xA5));
    }
    if (uniformResourceIdentifier != null) {
      children.add(
        asn1EncodeRaw(
          0x86,
          Uint8List.fromList(uniformResourceIdentifier!.codeUnits),
        ),
      );
    }
    if (iPAddress != null) {
      children.add(asn1EncodeRaw(0x87, iPAddress!));
    }
    if (registeredID != null) {
      children.add(asn1EncodeRaw(0x88, registeredID!));
    }
    if (tag != null) {
      return asn1EncodeConstructed(tag, children);
    }
    return children.isNotEmpty ? children.first : Uint8List(0);
  }

  factory GeneralName.fromAsn1(Asn1Node node) {
    AnotherName? otherName;
    String? rfc822Name;
    String? dNSName;
    ORAddress? x400Address;
    Name? directoryName;
    EDIPartyName? ediPartyName;
    String? uniformResourceIdentifier;
    Uint8List? iPAddress;
    Uint8List? registeredID;
    // CHOICE: check node's tag directly
    switch (node.tag) {
      case 0xA0:
        otherName = AnotherName.decode(node);
        break;
      case 0x81:
        rfc822Name = String.fromCharCodes(node.value);
        break;
      case 0x82:
        dNSName = String.fromCharCodes(node.value);
        break;
      case 0xA3:
        x400Address = ORAddress.decode(node);
        break;
      case 0xA4:
        directoryName = Name.decode(asn1Explicit(node));
        break;
      case 0xA5:
        ediPartyName = EDIPartyName.decode(node);
        break;
      case 0x86:
        uniformResourceIdentifier = String.fromCharCodes(node.value);
        break;
      case 0x87:
        iPAddress = node.value;
        break;
      case 0x88:
        registeredID = node.value;
        break;
    }
    return GeneralName._(
      otherName: otherName,
      rfc822Name: rfc822Name,
      dNSName: dNSName,
      x400Address: x400Address,
      directoryName: directoryName,
      ediPartyName: ediPartyName,
      uniformResourceIdentifier: uniformResourceIdentifier,
      iPAddress: iPAddress,
      registeredID: registeredID,
      asn1: node, // Store original node
    );
  }

  static GeneralName decode(dynamic data) {
    if (data is Asn1Node) {
      return GeneralName.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return GeneralName.fromAsn1(node);
      }
    }
    return GeneralName();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('GeneralName(');
    final otherNameVal = otherName;
    if (otherNameVal != null) {
      buffer.writeln(
        '  otherName: ${otherNameVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final rfc822NameVal = rfc822Name;
    if (rfc822NameVal != null) {
      buffer.writeln(
        '  rfc822Name: ${rfc822NameVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final dNSNameVal = dNSName;
    if (dNSNameVal != null) {
      buffer.writeln(
        '  dNSName: ${dNSNameVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final x400AddressVal = x400Address;
    if (x400AddressVal != null) {
      buffer.writeln(
        '  x400Address: ${x400AddressVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final directoryNameVal = directoryName;
    if (directoryNameVal != null) {
      buffer.writeln(
        '  directoryName: ${directoryNameVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final ediPartyNameVal = ediPartyName;
    if (ediPartyNameVal != null) {
      buffer.writeln(
        '  ediPartyName: ${ediPartyNameVal.toString().replaceAll("\n", "\n  ")},',
