      );
    }
    final iPAddressVal = iPAddress;
    if (iPAddressVal != null) {
      buffer.writeln('  iPAddress: ${asn1Hex(iPAddressVal)},');
    }
    final registeredIDVal = registeredID;
    if (registeredIDVal != null) {
      buffer.writeln('  registeredID: ${asn1Hex(registeredIDVal)},');
    }
    buffer.write(')');
    return buffer.toString();
