}

class AnotherName {
  final Uint8List? type_id;
  final Uint8List? value;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const AnotherName._({this.type_id, this.value, this.asn1});

  const AnotherName({Uint8List? type_id, Uint8List? value})
    : this._(type_id: type_id, value: value, asn1: null);

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (type_id != null) {
      children.add(asn1EncodeRaw(0x6, type_id!));
    }
    if (value != null) {
      children.add(asn1EncodeConstructed(0xA0, [asn1EncodeRaw(0x4, value!)]));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory AnotherName.fromAsn1(Asn1Node node) {
    Uint8List? type_id;
    Uint8List? value;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x6);
    if (found >= 0) {
      final child = node.children[found];
      type_id = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA0);
    if (found >= 0) {
      final child = node.children[found];
      value = asn1Explicit(child).value;
      childIdx = found + 1;
    }
    return AnotherName._(
      type_id: type_id,
      value: value,
      asn1: node, // Store original node
    );
  }

  static AnotherName decode(dynamic data) {
    if (data is Asn1Node) {
      return AnotherName.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return AnotherName.fromAsn1(node);
      }
    }
    return AnotherName();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('AnotherName(');
    final type_idVal = type_id;
    if (type_idVal != null) {
      buffer.writeln('  type_id: ${asn1Hex(type_idVal)},');
    }
    final valueVal = value;
    if (valueVal != null) {
      buffer.writeln('  value: ${asn1Hex(valueVal)},');
    }
    buffer.write(')');
    return buffer.toString();
  }
}

