class BasicConstraints {
  final bool? cA;
  final int? pathLenConstraint;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const BasicConstraints._({this.cA, this.pathLenConstraint, this.asn1});

  const BasicConstraints({bool? cA, int? pathLenConstraint})
    : this._(cA: cA, pathLenConstraint: pathLenConstraint, asn1: null);

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (cA != null) {
      children.add(asn1EncodeRaw(0x1, Uint8List.fromList([cA! ? 0xFF : 0x00])));
    }
    if (pathLenConstraint != null) {
      children.add(asn1EncodeRaw(0x2, asn1EncodeInt(pathLenConstraint!)));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory BasicConstraints.fromAsn1(Asn1Node node) {
    bool? cA;
    int? pathLenConstraint;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x1);
    if (found >= 0) {
      final child = node.children[found];
      cA = child.value.isNotEmpty && child.value.first != 0;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x2);
    if (found >= 0) {
      final child = node.children[found];
      pathLenConstraint = asn1DecodeInt(child.value);
      childIdx = found + 1;
    }
    return BasicConstraints._(
      cA: cA,
      pathLenConstraint: pathLenConstraint,
      asn1: node, // Store original node
    );
  }

  static BasicConstraints decode(dynamic data) {
    if (data is Asn1Node) {
      return BasicConstraints.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return BasicConstraints.fromAsn1(node);
      }
    }
    return BasicConstraints();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('BasicConstraints(');
    final cAVal = cA;
    if (cAVal != null) {
      buffer.writeln('  cA: ${cAVal.toString().replaceAll("\n", "\n  ")},');
    }
    final pathLenConstraintVal = pathLenConstraint;
    if (pathLenConstraintVal != null) {
      buffer.writeln(
        '  pathLenConstraint: ${pathLenConstraintVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class NameConstraints {
  final GeneralSubtrees? permittedSubtrees;
  final GeneralSubtrees? excludedSubtrees;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const NameConstraints._({
    this.permittedSubtrees,
    this.excludedSubtrees,
    this.asn1,
  });

  const NameConstraints({
    GeneralSubtrees? permittedSubtrees,
    GeneralSubtrees? excludedSubtrees,
  }) : this._(
         permittedSubtrees: permittedSubtrees,
         excludedSubtrees: excludedSubtrees,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (permittedSubtrees != null) {
      final items = <Uint8List>[];
      for (final v in permittedSubtrees!) {
        items.add(v.encode(tag: 0x30));
      }
      children.add(asn1EncodeConstructed(0xA0, items));
    }
    if (excludedSubtrees != null) {
      final items = <Uint8List>[];
      for (final v in excludedSubtrees!) {
        items.add(v.encode(tag: 0x30));
      }
      children.add(asn1EncodeConstructed(0xA1, items));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory NameConstraints.fromAsn1(Asn1Node node) {
    GeneralSubtrees? permittedSubtrees;
    GeneralSubtrees? excludedSubtrees;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0xA0);
    if (found >= 0) {
      final child = node.children[found];
      final items = <GeneralSubtree>[];
      for (final n in child.children) {
        items.add(GeneralSubtree.decode(n));
      }
      permittedSubtrees = items;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA1);
    if (found >= 0) {
      final child = node.children[found];
      final items = <GeneralSubtree>[];
      for (final n in child.children) {
        items.add(GeneralSubtree.decode(n));
      }
      excludedSubtrees = items;
      childIdx = found + 1;
    }
    return NameConstraints._(
      permittedSubtrees: permittedSubtrees,
      excludedSubtrees: excludedSubtrees,
      asn1: node, // Store original node
    );
  }

  static NameConstraints decode(dynamic data) {
    if (data is Asn1Node) {
      return NameConstraints.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return NameConstraints.fromAsn1(node);
      }
    }
    return NameConstraints();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('NameConstraints(');
    final permittedSubtreesVal = permittedSubtrees;
    if (permittedSubtreesVal != null) {
      buffer.writeln(
        '  permittedSubtrees: [${permittedSubtreesVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    final excludedSubtreesVal = excludedSubtrees;
    if (excludedSubtreesVal != null) {
      buffer.writeln(
        '  excludedSubtrees: [${excludedSubtreesVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class GeneralSubtree {
  final GeneralName? base;
  final BaseDistance? minimum;
  final BaseDistance? maximum;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const GeneralSubtree._({this.base, this.minimum, this.maximum, this.asn1});

  const GeneralSubtree({
    GeneralName? base,
    BaseDistance? minimum,
    BaseDistance? maximum,
  }) : this._(base: base, minimum: minimum, maximum: maximum, asn1: null);

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (base != null) {
      children.add(base!.encode());
    }
    if (minimum != null) {
      children.add(asn1EncodeRaw(0x80, minimum!));
    }
    if (maximum != null) {
      children.add(asn1EncodeRaw(0x81, maximum!));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory GeneralSubtree.fromAsn1(Asn1Node node) {
    GeneralName? base;
    BaseDistance? minimum;
    BaseDistance? maximum;
    int childIdx = 0;
    int found;
    if (childIdx < node.children.length) {
      final child = node.children[childIdx];
      base = GeneralName.decode(child);
      childIdx++;
    }
    found = asn1SeekTag(node.children, childIdx, 0x80);
    if (found >= 0) {
      final child = node.children[found];
      minimum = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x81);
    if (found >= 0) {
      final child = node.children[found];
      maximum = child.value;
      childIdx = found + 1;
    }
    return GeneralSubtree._(
      base: base,
      minimum: minimum,
      maximum: maximum,
      asn1: node, // Store original node
    );
  }

  static GeneralSubtree decode(dynamic data) {
    if (data is Asn1Node) {
      return GeneralSubtree.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return GeneralSubtree.fromAsn1(node);
      }
    }
    return GeneralSubtree();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('GeneralSubtree(');
    final baseVal = base;
    if (baseVal != null) {
      buffer.writeln('  base: ${baseVal.toString().replaceAll("\n", "\n  ")},');
    }
    final minimumVal = minimum;
    if (minimumVal != null) {
      buffer.writeln('  minimum: ${asn1Hex(minimumVal)},');
    }
    final maximumVal = maximum;
    if (maximumVal != null) {
      buffer.writeln('  maximum: ${asn1Hex(maximumVal)},');
    }
    buffer.write(')');
    return buffer.toString();
  }
}

