    this.asn1,
  });

  const PolicyConstraints({
    SkipCerts? requireExplicitPolicy,
    SkipCerts? inhibitPolicyMapping,
  }) : this._(
         requireExplicitPolicy: requireExplicitPolicy,
         inhibitPolicyMapping: inhibitPolicyMapping,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (requireExplicitPolicy != null) {
      children.add(asn1EncodeRaw(0x80, requireExplicitPolicy!));
    }
    if (inhibitPolicyMapping != null) {
      children.add(asn1EncodeRaw(0x81, inhibitPolicyMapping!));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory PolicyConstraints.fromAsn1(Asn1Node node) {
    SkipCerts? requireExplicitPolicy;
    SkipCerts? inhibitPolicyMapping;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x80);
    if (found >= 0) {
      final child = node.children[found];
      requireExplicitPolicy = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x81);
    if (found >= 0) {
      final child = node.children[found];
      inhibitPolicyMapping = child.value;
      childIdx = found + 1;
    }
    return PolicyConstraints._(
      requireExplicitPolicy: requireExplicitPolicy,
      inhibitPolicyMapping: inhibitPolicyMapping,
      asn1: node, // Store original node
    );
  }

  static PolicyConstraints decode(dynamic data) {
    if (data is Asn1Node) {
      return PolicyConstraints.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return PolicyConstraints.fromAsn1(node);
      }
    }
    return PolicyConstraints();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('PolicyConstraints(');
    final requireExplicitPolicyVal = requireExplicitPolicy;
    if (requireExplicitPolicyVal != null) {
      buffer.writeln(
        '  requireExplicitPolicy: ${asn1Hex(requireExplicitPolicyVal)},',
      );
    }
    final inhibitPolicyMappingVal = inhibitPolicyMapping;
    if (inhibitPolicyMappingVal != null) {
      buffer.writeln(
        '  inhibitPolicyMapping: ${asn1Hex(inhibitPolicyMappingVal)},',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class DistributionPoint {
  final DistributionPointName? distributionPoint;
  final ReasonFlags? reasons;
  final GeneralNames? cRLIssuer;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const DistributionPoint._({
    this.distributionPoint,
    this.reasons,
    this.cRLIssuer,
    this.asn1,
  });

  const DistributionPoint({
    DistributionPointName? distributionPoint,
    ReasonFlags? reasons,
    GeneralNames? cRLIssuer,
  }) : this._(
         distributionPoint: distributionPoint,
         reasons: reasons,
         cRLIssuer: cRLIssuer,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (distributionPoint != null) {
      children.add(asn1EncodeConstructed(0xA0, [distributionPoint!.encode()]));
    }
    if (reasons != null) {
      children.add(asn1EncodeRaw(0x81, asn1EncodeBits(reasons!.value)));
    }
    if (cRLIssuer != null) {
      final items = <Uint8List>[];
      for (final v in cRLIssuer!) {
        items.add(v.encode());
      }
      children.add(asn1EncodeConstructed(0xA2, items));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory DistributionPoint.fromAsn1(Asn1Node node) {
    DistributionPointName? distributionPoint;
    ReasonFlags? reasons;
    GeneralNames? cRLIssuer;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0xA0);
    if (found >= 0) {
      final child = node.children[found];
      distributionPoint = DistributionPointName.decode(asn1Explicit(child));
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x81);
    if (found >= 0) {
      final child = node.children[found];
      reasons = ReasonFlags(asn1DecodeBits(child.value));
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA2);
    if (found >= 0) {
      final child = node.children[found];
      final items = <GeneralName>[];
      for (final n in child.children) {
        items.add(GeneralName.decode(n));
      }
      cRLIssuer = items;
      childIdx = found + 1;
    }
    return DistributionPoint._(
      distributionPoint: distributionPoint,
      reasons: reasons,
      cRLIssuer: cRLIssuer,
      asn1: node, // Store original node
    );
  }

  static DistributionPoint decode(dynamic data) {
    if (data is Asn1Node) {
      return DistributionPoint.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return DistributionPoint.fromAsn1(node);
      }
    }
    return DistributionPoint();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('DistributionPoint(');
    final distributionPointVal = distributionPoint;
    if (distributionPointVal != null) {
      buffer.writeln(
        '  distributionPoint: ${distributionPointVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final reasonsVal = reasons;
    if (reasonsVal != null) {
      buffer.writeln(
        '  reasons: ${reasonsVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final cRLIssuerVal = cRLIssuer;
    if (cRLIssuerVal != null) {
      buffer.writeln(
        '  cRLIssuer: [${cRLIssuerVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class DistributionPointName {
  final GeneralNames? fullName;
  final RelativeDistinguishedName? nameRelativeToCRLIssuer;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const DistributionPointName._({
    this.fullName,
    this.nameRelativeToCRLIssuer,
    this.asn1,
  });

  const DistributionPointName({
    GeneralNames? fullName,
    RelativeDistinguishedName? nameRelativeToCRLIssuer,
  }) : this._(
         fullName: fullName,
         nameRelativeToCRLIssuer: nameRelativeToCRLIssuer,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (fullName != null) {
      final items = <Uint8List>[];
      for (final v in fullName!) {
        items.add(v.encode());
      }
      children.add(asn1EncodeConstructed(0xA0, items));
    }
    if (nameRelativeToCRLIssuer != null) {
      final items = <Uint8List>[];
      for (final v in nameRelativeToCRLIssuer!) {
        items.add(v.encode(tag: 0x30));
      }
      children.add(asn1EncodeConstructed(0xA1, items));
    }
    if (tag != null) {
      return asn1EncodeConstructed(tag, children);
    }
    return children.isNotEmpty ? children.first : Uint8List(0);
  }

  factory DistributionPointName.fromAsn1(Asn1Node node) {
    GeneralNames? fullName;
    RelativeDistinguishedName? nameRelativeToCRLIssuer;
    // CHOICE: check node's tag directly
    switch (node.tag) {
      case 0xA0:
        final items = <GeneralName>[];
        for (final n in node.children) {
          items.add(GeneralName.decode(n));
        }
        fullName = items;
        break;
      case 0xA1:
        final items = <AttributeTypeAndValue>[];
        for (final n in node.children) {
          items.add(AttributeTypeAndValue.decode(n));
        }
        nameRelativeToCRLIssuer = items;
        break;
    }
    return DistributionPointName._(
      fullName: fullName,
      nameRelativeToCRLIssuer: nameRelativeToCRLIssuer,
      asn1: node, // Store original node
    );
  }

  static DistributionPointName decode(dynamic data) {
    if (data is Asn1Node) {
      return DistributionPointName.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return DistributionPointName.fromAsn1(node);
      }
    }
    return DistributionPointName();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('DistributionPointName(');
    final fullNameVal = fullName;
    if (fullNameVal != null) {
      buffer.writeln(
        '  fullName: [${fullNameVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    final nameRelativeToCRLIssuerVal = nameRelativeToCRLIssuer;
    if (nameRelativeToCRLIssuerVal != null) {
      buffer.writeln(
        '  nameRelativeToCRLIssuer: [${nameRelativeToCRLIssuerVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class AccessDescription {
  final Uint8List? accessMethod;
  final GeneralName? accessLocation;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const AccessDescription._({
    this.accessMethod,
    this.accessLocation,
    this.asn1,
  });

  const AccessDescription({
    Uint8List? accessMethod,
    GeneralName? accessLocation,
  }) : this._(
         accessMethod: accessMethod,
         accessLocation: accessLocation,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (accessMethod != null) {
      children.add(asn1EncodeRaw(0x6, accessMethod!));
    }
    if (accessLocation != null) {
      children.add(accessLocation!.encode());
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory AccessDescription.fromAsn1(Asn1Node node) {
    Uint8List? accessMethod;
    GeneralName? accessLocation;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x6);
    if (found >= 0) {
      final child = node.children[found];
      accessMethod = child.value;
      childIdx = found + 1;
    }
    if (childIdx < node.children.length) {
      final child = node.children[childIdx];
      accessLocation = GeneralName.decode(child);
      childIdx++;
    }
    return AccessDescription._(
      accessMethod: accessMethod,
      accessLocation: accessLocation,
      asn1: node, // Store original node
    );
  }

  static AccessDescription decode(dynamic data) {
    if (data is Asn1Node) {
      return AccessDescription.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return AccessDescription.fromAsn1(node);
      }
    }
    return AccessDescription();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('AccessDescription(');
    final accessMethodVal = accessMethod;
    if (accessMethodVal != null) {
      buffer.writeln('  accessMethod: ${asn1Hex(accessMethodVal)},');
    }
    final accessLocationVal = accessLocation;
    if (accessLocationVal != null) {
      buffer.writeln(
        '  accessLocation: ${accessLocationVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class IssuingDistributionPoint {
  final DistributionPointName? distributionPoint;
  final bool? onlyContainsUserCerts;
  final bool? onlyContainsCACerts;
  final ReasonFlags? onlySomeReasons;
  final bool? indirectCRL;
  final bool? onlyContainsAttributeCerts;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const IssuingDistributionPoint._({
    this.distributionPoint,
    this.onlyContainsUserCerts,
    this.onlyContainsCACerts,
    this.onlySomeReasons,
    this.indirectCRL,
    this.onlyContainsAttributeCerts,
    this.asn1,
  });

  const IssuingDistributionPoint({
    DistributionPointName? distributionPoint,
    bool? onlyContainsUserCerts,
    bool? onlyContainsCACerts,
    ReasonFlags? onlySomeReasons,
    bool? indirectCRL,
    bool? onlyContainsAttributeCerts,
  }) : this._(
         distributionPoint: distributionPoint,
         onlyContainsUserCerts: onlyContainsUserCerts,
         onlyContainsCACerts: onlyContainsCACerts,
         onlySomeReasons: onlySomeReasons,
         indirectCRL: indirectCRL,
         onlyContainsAttributeCerts: onlyContainsAttributeCerts,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (distributionPoint != null) {
      children.add(asn1EncodeConstructed(0xA0, [distributionPoint!.encode()]));
    }
    if (onlyContainsUserCerts != null) {
      children.add(
        asn1EncodeRaw(
          0x81,
          Uint8List.fromList([onlyContainsUserCerts! ? 0xFF : 0x00]),
        ),
      );
    }
    if (onlyContainsCACerts != null) {
      children.add(
        asn1EncodeRaw(
          0x82,
          Uint8List.fromList([onlyContainsCACerts! ? 0xFF : 0x00]),
        ),
      );
    }
    if (onlySomeReasons != null) {
      children.add(asn1EncodeRaw(0x83, asn1EncodeBits(onlySomeReasons!.value)));
    }
    if (indirectCRL != null) {
      children.add(
        asn1EncodeRaw(0x84, Uint8List.fromList([indirectCRL! ? 0xFF : 0x00])),
      );
    }
    if (onlyContainsAttributeCerts != null) {
      children.add(
        asn1EncodeRaw(
          0x85,
          Uint8List.fromList([onlyContainsAttributeCerts! ? 0xFF : 0x00]),
        ),
      );
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory IssuingDistributionPoint.fromAsn1(Asn1Node node) {
    DistributionPointName? distributionPoint;
    bool? onlyContainsUserCerts;
    bool? onlyContainsCACerts;
    ReasonFlags? onlySomeReasons;
    bool? indirectCRL;
    bool? onlyContainsAttributeCerts;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0xA0);
    if (found >= 0) {
      final child = node.children[found];
      distributionPoint = DistributionPointName.decode(asn1Explicit(child));
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x81);
    if (found >= 0) {
      final child = node.children[found];
      onlyContainsUserCerts = child.value.isNotEmpty && child.value.first != 0;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x82);
    if (found >= 0) {
      final child = node.children[found];
      onlyContainsCACerts = child.value.isNotEmpty && child.value.first != 0;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x83);
    if (found >= 0) {
      final child = node.children[found];
      onlySomeReasons = ReasonFlags(asn1DecodeBits(child.value));
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x84);
    if (found >= 0) {
      final child = node.children[found];
      indirectCRL = child.value.isNotEmpty && child.value.first != 0;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x85);
    if (found >= 0) {
      final child = node.children[found];
      onlyContainsAttributeCerts =
          child.value.isNotEmpty && child.value.first != 0;
      childIdx = found + 1;
    }
    return IssuingDistributionPoint._(
      distributionPoint: distributionPoint,
      onlyContainsUserCerts: onlyContainsUserCerts,
      onlyContainsCACerts: onlyContainsCACerts,
      onlySomeReasons: onlySomeReasons,
      indirectCRL: indirectCRL,
      onlyContainsAttributeCerts: onlyContainsAttributeCerts,
      asn1: node, // Store original node
    );
  }

  static IssuingDistributionPoint decode(dynamic data) {
    if (data is Asn1Node) {
      return IssuingDistributionPoint.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return IssuingDistributionPoint.fromAsn1(node);
      }
    }
    return IssuingDistributionPoint();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('IssuingDistributionPoint(');
    final distributionPointVal = distributionPoint;
    if (distributionPointVal != null) {
      buffer.writeln(
        '  distributionPoint: ${distributionPointVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final onlyContainsUserCertsVal = onlyContainsUserCerts;
    if (onlyContainsUserCertsVal != null) {
      buffer.writeln(
        '  onlyContainsUserCerts: ${onlyContainsUserCertsVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final onlyContainsCACertsVal = onlyContainsCACerts;
    if (onlyContainsCACertsVal != null) {
      buffer.writeln(
        '  onlyContainsCACerts: ${onlyContainsCACertsVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final onlySomeReasonsVal = onlySomeReasons;
    if (onlySomeReasonsVal != null) {
      buffer.writeln(
        '  onlySomeReasons: ${onlySomeReasonsVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final indirectCRLVal = indirectCRL;
    if (indirectCRLVal != null) {
      buffer.writeln(
        '  indirectCRL: ${indirectCRLVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final onlyContainsAttributeCertsVal = onlyContainsAttributeCerts;
    if (onlyContainsAttributeCertsVal != null) {
      buffer.writeln(
        '  onlyContainsAttributeCerts: ${onlyContainsAttributeCertsVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class PEHeader {
  final Uint8List? mandated;
  final UInt15? identification;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const PEHeader._({this.mandated, this.identification, this.asn1});

  const PEHeader({Uint8List? mandated, UInt15? identification})
    : this._(mandated: mandated, identification: identification, asn1: null);

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (mandated != null) {
      children.add(asn1EncodeRaw(0x80, mandated!));
    }
    if (identification != null) {
      children.add(asn1EncodeRaw(0x81, identification!));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory PEHeader.fromAsn1(Asn1Node node) {
    Uint8List? mandated;
    UInt15? identification;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x80);
    if (found >= 0) {
      final child = node.children[found];
      mandated = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x81);
    if (found >= 0) {
      final child = node.children[found];
      identification = child.value;
      childIdx = found + 1;
    }
    return PEHeader._(
      mandated: mandated,
      identification: identification,
      asn1: node, // Store original node
    );
  }

  static PEHeader decode(dynamic data) {
    if (data is Asn1Node) {
      return PEHeader.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return PEHeader.fromAsn1(node);
      }
    }
    return PEHeader();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('PEHeader(');
    final mandatedVal = mandated;
    if (mandatedVal != null) {
      buffer.writeln('  mandated: ${asn1Hex(mandatedVal)},');
    }
    final identificationVal = identification;
    if (identificationVal != null) {
      buffer.writeln('  identification: ${asn1Hex(identificationVal)},');
    }
    buffer.write(')');
    return buffer.toString();
  }
}

