class ProprietaryInfo {
  final Uint8List? specialFileInformation;
  final Uint8List? fillPattern;
  final Uint8List? repeatPattern;
  final Uint8List? maximumFileSize;
  final Uint8List? fileDetails;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const ProprietaryInfo._({
    this.specialFileInformation,
    this.fillPattern,
    this.repeatPattern,
    this.maximumFileSize,
    this.fileDetails,
    this.asn1,
  });

  const ProprietaryInfo({
    Uint8List? specialFileInformation,
    Uint8List? fillPattern,
    Uint8List? repeatPattern,
    Uint8List? maximumFileSize,
    Uint8List? fileDetails,
  }) : this._(
         specialFileInformation: specialFileInformation,
         fillPattern: fillPattern,
         repeatPattern: repeatPattern,
         maximumFileSize: maximumFileSize,
         fileDetails: fileDetails,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (specialFileInformation != null) {
      children.add(asn1EncodeRaw(0xC0, specialFileInformation!));
    }
    if (fillPattern != null) {
      children.add(asn1EncodeRaw(0xC1, fillPattern!));
    }
    if (repeatPattern != null) {
      children.add(asn1EncodeRaw(0xC2, repeatPattern!));
    }
    if (maximumFileSize != null) {
      children.add(asn1EncodeRaw(0x86, maximumFileSize!));
    }
    if (fileDetails != null) {
      children.add(asn1EncodeRaw(0x84, fileDetails!));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory ProprietaryInfo.fromAsn1(Asn1Node node) {
    Uint8List? specialFileInformation;
    Uint8List? fillPattern;
    Uint8List? repeatPattern;
    Uint8List? maximumFileSize;
    Uint8List? fileDetails;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0xC0);
    if (found >= 0) {
      final child = node.children[found];
      specialFileInformation = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xC1);
    if (found >= 0) {
      final child = node.children[found];
      fillPattern = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xC2);
    if (found >= 0) {
      final child = node.children[found];
      repeatPattern = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x86);
    if (found >= 0) {
      final child = node.children[found];
      maximumFileSize = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x84);
    if (found >= 0) {
      final child = node.children[found];
      fileDetails = child.value;
      childIdx = found + 1;
    }
    return ProprietaryInfo._(
      specialFileInformation: specialFileInformation,
      fillPattern: fillPattern,
      repeatPattern: repeatPattern,
      maximumFileSize: maximumFileSize,
      fileDetails: fileDetails,
      asn1: node, // Store original node
    );
  }

  static ProprietaryInfo decode(dynamic data) {
    if (data is Asn1Node) {
      return ProprietaryInfo.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return ProprietaryInfo.fromAsn1(node);
      }
    }
    return ProprietaryInfo();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('ProprietaryInfo(');
    final specialFileInformationVal = specialFileInformation;
    if (specialFileInformationVal != null) {
      buffer.writeln(
        '  specialFileInformation: ${asn1Hex(specialFileInformationVal)},',
      );
    }
    final fillPatternVal = fillPattern;
    if (fillPatternVal != null) {
      buffer.writeln('  fillPattern: ${asn1Hex(fillPatternVal)},');
    }
    final repeatPatternVal = repeatPattern;
    if (repeatPatternVal != null) {
      buffer.writeln('  repeatPattern: ${asn1Hex(repeatPatternVal)},');
    }
    final maximumFileSizeVal = maximumFileSize;
    if (maximumFileSizeVal != null) {
      buffer.writeln('  maximumFileSize: ${asn1Hex(maximumFileSizeVal)},');
    }
    final fileDetailsVal = fileDetails;
    if (fileDetailsVal != null) {
      buffer.writeln('  fileDetails: ${asn1Hex(fileDetailsVal)},');
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class Fcp {
  final Uint8List? fileDescriptor;
  final Uint8List? fileID;
  final ApplicationIdentifier? dfName;
  final Uint8List? lcsi;
  final Uint8List? securityAttributesReferenced;
  final Uint8List? efFileSize;
  final Uint8List? pinStatusTemplateDO;
  final Uint8List? shortEFID;
