      linkPath = child.value;
      childIdx = found + 1;
    }
    return Fcp._(
      fileDescriptor: fileDescriptor,
      fileID: fileID,
      dfName: dfName,
      lcsi: lcsi,
      securityAttributesReferenced: securityAttributesReferenced,
      efFileSize: efFileSize,
      pinStatusTemplateDO: pinStatusTemplateDO,
