class File__item_ {
  final Uint8List? doNotCreate;
  final Fcp? fileDescriptor;
  final UInt16? fillFileOffset;
  final Uint8List? fillFileContent;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const File__item_._({
    this.doNotCreate,
    this.fileDescriptor,
    this.fillFileOffset,
    this.fillFileContent,
    this.asn1,
  });

  const File__item_({
    Uint8List? doNotCreate,
    Fcp? fileDescriptor,
    UInt16? fillFileOffset,
    Uint8List? fillFileContent,
  }) : this._(
         doNotCreate: doNotCreate,
         fileDescriptor: fileDescriptor,
         fillFileOffset: fillFileOffset,
         fillFileContent: fillFileContent,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (doNotCreate != null) {
      children.add(asn1EncodeRaw(0x80, doNotCreate!));
    }
    if (fileDescriptor != null) {
      children.add(fileDescriptor!.encode(tag: 0xA1));
    }
    if (fillFileOffset != null) {
      children.add(asn1EncodeRaw(0x82, fillFileOffset!));
    }
    if (fillFileContent != null) {
      children.add(asn1EncodeRaw(0x83, fillFileContent!));
    }
    if (tag != null) {
      return asn1EncodeConstructed(tag, children);
    }
    return children.isNotEmpty ? children.first : Uint8List(0);
  }

  factory File__item_.fromAsn1(Asn1Node node) {
    Uint8List? doNotCreate;
    Fcp? fileDescriptor;
    UInt16? fillFileOffset;
    Uint8List? fillFileContent;
    // CHOICE: check node's tag directly
    switch (node.tag) {
      case 0x80:
        doNotCreate = node.value;
        break;
      case 0xA1:
        fileDescriptor = Fcp.decode(node);
        break;
      case 0x82:
        fillFileOffset = node.value;
        break;
      case 0x83:
        fillFileContent = node.value;
        break;
    }
    return File__item_._(
      doNotCreate: doNotCreate,
      fileDescriptor: fileDescriptor,
      fillFileOffset: fillFileOffset,
      fillFileContent: fillFileContent,
      asn1: node, // Store original node
    );
  }

  static File__item_ decode(dynamic data) {
    if (data is Asn1Node) {
      return File__item_.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return File__item_.fromAsn1(node);
      }
    }
    return File__item_();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('File__item_(');
    final doNotCreateVal = doNotCreate;
    if (doNotCreateVal != null) {
      buffer.writeln('  doNotCreate: ${asn1Hex(doNotCreateVal)},');
    }
    final fileDescriptorVal = fileDescriptor;
    if (fileDescriptorVal != null) {
      buffer.writeln(
        '  fileDescriptor: ${fileDescriptorVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final fillFileOffsetVal = fillFileOffset;
    if (fillFileOffsetVal != null) {
      buffer.writeln('  fillFileOffset: ${asn1Hex(fillFileOffsetVal)},');
    }
    final fillFileContentVal = fillFileContent;
    if (fillFileContentVal != null) {
