  static PE_TELECOM decode(dynamic data) {
    if (data is Asn1Node) {
      return PE_TELECOM.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return PE_TELECOM.fromAsn1(node);
      }
    }
    return PE_TELECOM();
  }

