class PE_EAP {
  final PEHeader? eap_header;
  final Uint8List? templateID;
  final File? df_eap;
  final File? ef_eapkeys;
  final File? ef_eapstatus;
  final File? ef_puid;
  final File? ef_ps;
  final File? ef_curid;
  final File? ef_reid;
  final File? ef_realm;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const PE_EAP._({
    this.eap_header,
    this.templateID,
    this.df_eap,
    this.ef_eapkeys,
    this.ef_eapstatus,
    this.ef_puid,
    this.ef_ps,
    this.ef_curid,
    this.ef_reid,
    this.ef_realm,
    this.asn1,
  });

  const PE_EAP({
    PEHeader? eap_header,
    Uint8List? templateID,
    File? df_eap,
    File? ef_eapkeys,
    File? ef_eapstatus,
    File? ef_puid,
    File? ef_ps,
    File? ef_curid,
    File? ef_reid,
    File? ef_realm,
  }) : this._(
         eap_header: eap_header,
         templateID: templateID,
         df_eap: df_eap,
         ef_eapkeys: ef_eapkeys,
         ef_eapstatus: ef_eapstatus,
         ef_puid: ef_puid,
         ef_ps: ef_ps,
         ef_curid: ef_curid,
         ef_reid: ef_reid,
         ef_realm: ef_realm,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (eap_header != null) {
      children.add(eap_header!.encode(tag: 0xA0));
    }
    if (templateID != null) {
      children.add(asn1EncodeRaw(0x81, templateID!));
    }
    if (df_eap != null) {
      final items = <Uint8List>[];
      for (final v in df_eap!) {
        items.add(v.encode());
      }
      children.add(asn1EncodeConstructed(0xA2, items));
    }
    if (ef_eapkeys != null) {
      final items = <Uint8List>[];
      for (final v in ef_eapkeys!) {
        items.add(v.encode());
      }
      children.add(asn1EncodeConstructed(0xA3, items));
    }
    if (ef_eapstatus != null) {
      final items = <Uint8List>[];
      for (final v in ef_eapstatus!) {
        items.add(v.encode());
      }
      children.add(asn1EncodeConstructed(0xA4, items));
    }
    if (ef_puid != null) {
      final items = <Uint8List>[];
      for (final v in ef_puid!) {
        items.add(v.encode());
      }
