        items.add(File__item_.decode(n));
      }
      df_eap = items;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA3);
    if (found >= 0) {
      final child = node.children[found];
      final items = <File__item_>[];
      for (final n in child.children) {
        items.add(File__item_.decode(n));
      }
      ef_eapkeys = items;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA4);
    if (found >= 0) {
      final child = node.children[found];
      final items = <File__item_>[];
      for (final n in child.children) {
        items.add(File__item_.decode(n));
      }
      ef_eapstatus = items;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA5);
    if (found >= 0) {
      final child = node.children[found];
