      for (final n in child.children) {
        items.add(File__item_.decode(n));
      }
      ef_realm = items;
      childIdx = found + 1;
    }
    return PE_EAP._(
      eap_header: eap_header,
      templateID: templateID,
      df_eap: df_eap,
      ef_eapkeys: ef_eapkeys,
      ef_eapstatus: ef_eapstatus,
      ef_puid: ef_puid,
      ef_ps: ef_ps,
      ef_curid: ef_curid,
      ef_reid: ef_reid,
      ef_realm: ef_realm,
