    );
  }

  static PE_EAP decode(dynamic data) {
    if (data is Asn1Node) {
      return PE_EAP.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return PE_EAP.fromAsn1(node);
      }
    }
    return PE_EAP();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('PE_EAP(');
    final eap_headerVal = eap_header;
    if (eap_headerVal != null) {
      buffer.writeln(
        '  eap_header: ${eap_headerVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final templateIDVal = templateID;
    if (templateIDVal != null) {
      buffer.writeln('  templateID: ${asn1Hex(templateIDVal)},');
    }
    final df_eapVal = df_eap;
    if (df_eapVal != null) {
      buffer.writeln(
        '  df_eap: [${df_eapVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    final ef_eapkeysVal = ef_eapkeys;
    if (ef_eapkeysVal != null) {
      buffer.writeln(
        '  ef_eapkeys: [${ef_eapkeysVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    final ef_eapstatusVal = ef_eapstatus;
    if (ef_eapstatusVal != null) {
      buffer.writeln(
        '  ef_eapstatus: [${ef_eapstatusVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    final ef_puidVal = ef_puid;
    if (ef_puidVal != null) {
      buffer.writeln(
        '  ef_puid: [${ef_puidVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    final ef_psVal = ef_ps;
    if (ef_psVal != null) {
      buffer.writeln(
        '  ef_ps: [${ef_psVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    final ef_curidVal = ef_curid;
    if (ef_curidVal != null) {
      buffer.writeln(
        '  ef_curid: [${ef_curidVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    final ef_reidVal = ef_reid;
    if (ef_reidVal != null) {
      buffer.writeln(
        '  ef_reid: [${ef_reidVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    final ef_realmVal = ef_realm;
    if (ef_realmVal != null) {
      buffer.writeln(
        '  ef_realm: [${ef_realmVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
