class PE_SSIM {
  final PEHeader? ssim_header;
  final Uint8List? templateID;
  final File? adf_ssim;
  final File? ef_arr;
  final File? ef_eapId;
  final File? ef_nssai;
  final File? ef_eapStatus;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const PE_SSIM._({
    this.ssim_header,
    this.templateID,
    this.adf_ssim,
    this.ef_arr,
    this.ef_eapId,
    this.ef_nssai,
    this.ef_eapStatus,
    this.asn1,
  });

  const PE_SSIM({
    PEHeader? ssim_header,
    Uint8List? templateID,
    File? adf_ssim,
    File? ef_arr,
    File? ef_eapId,
    File? ef_nssai,
    File? ef_eapStatus,
  }) : this._(
         ssim_header: ssim_header,
         templateID: templateID,
         adf_ssim: adf_ssim,
         ef_arr: ef_arr,
         ef_eapId: ef_eapId,
         ef_nssai: ef_nssai,
         ef_eapStatus: ef_eapStatus,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (ssim_header != null) {
      children.add(ssim_header!.encode(tag: 0xA0));
    }
    if (templateID != null) {
      children.add(asn1EncodeRaw(0x81, templateID!));
    }
    if (adf_ssim != null) {
      final items = <Uint8List>[];
      for (final v in adf_ssim!) {
        items.add(v.encode());
      }
      children.add(asn1EncodeConstructed(0xA2, items));
    }
    if (ef_arr != null) {
      final items = <Uint8List>[];
      for (final v in ef_arr!) {
        items.add(v.encode());
      }
      children.add(asn1EncodeConstructed(0xA3, items));
    }
    if (ef_eapId != null) {
      final items = <Uint8List>[];
      for (final v in ef_eapId!) {
        items.add(v.encode());
      }
      children.add(asn1EncodeConstructed(0xA4, items));
    }
    if (ef_nssai != null) {
      final items = <Uint8List>[];
      for (final v in ef_nssai!) {
        items.add(v.encode());
      }
      children.add(asn1EncodeConstructed(0xA5, items));
    }
    if (ef_eapStatus != null) {
      final items = <Uint8List>[];
      for (final v in ef_eapStatus!) {
        items.add(v.encode());
      }
      children.add(asn1EncodeConstructed(0xA6, items));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory PE_SSIM.fromAsn1(Asn1Node node) {
    PEHeader? ssim_header;
    Uint8List? templateID;
    File? adf_ssim;
    File? ef_arr;
    File? ef_eapId;
    File? ef_nssai;
    File? ef_eapStatus;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0xA0);
    if (found >= 0) {
      final child = node.children[found];
      ssim_header = PEHeader.decode(child);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x81);
    if (found >= 0) {
      final child = node.children[found];
      templateID = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA2);
    if (found >= 0) {
      final child = node.children[found];
      final items = <File__item_>[];
      for (final n in child.children) {
        items.add(File__item_.decode(n));
      }
      adf_ssim = items;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA3);
    if (found >= 0) {
      final child = node.children[found];
      final items = <File__item_>[];
      for (final n in child.children) {
        items.add(File__item_.decode(n));
      }
      ef_arr = items;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA4);
    if (found >= 0) {
      final child = node.children[found];
      final items = <File__item_>[];
      for (final n in child.children) {
        items.add(File__item_.decode(n));
      }
      ef_eapId = items;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA5);
    if (found >= 0) {
      final child = node.children[found];
      final items = <File__item_>[];
      for (final n in child.children) {
        items.add(File__item_.decode(n));
      }
      ef_nssai = items;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA6);
    if (found >= 0) {
      final child = node.children[found];
      final items = <File__item_>[];
      for (final n in child.children) {
        items.add(File__item_.decode(n));
      }
      ef_eapStatus = items;
      childIdx = found + 1;
    }
    return PE_SSIM._(
      ssim_header: ssim_header,
      templateID: templateID,
      adf_ssim: adf_ssim,
      ef_arr: ef_arr,
      ef_eapId: ef_eapId,
      ef_nssai: ef_nssai,
      ef_eapStatus: ef_eapStatus,
      asn1: node, // Store original node
    );
  }

  static PE_SSIM decode(dynamic data) {
    if (data is Asn1Node) {
      return PE_SSIM.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return PE_SSIM.fromAsn1(node);
      }
    }
    return PE_SSIM();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('PE_SSIM(');
    final ssim_headerVal = ssim_header;
    if (ssim_headerVal != null) {
      buffer.writeln(
        '  ssim_header: ${ssim_headerVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final templateIDVal = templateID;
    if (templateIDVal != null) {
      buffer.writeln('  templateID: ${asn1Hex(templateIDVal)},');
    }
    final adf_ssimVal = adf_ssim;
    if (adf_ssimVal != null) {
      buffer.writeln(
        '  adf_ssim: [${adf_ssimVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
