    if (gfm_header != null) {
      children.add(gfm_header!.encode(tag: 0xA0));
    }
    if (fileManagementCMD != null) {
      final items = <Uint8List>[];
      for (final v in fileManagementCMD!) {
        items.add(v.encode());
