    found = asn1SeekTag(node.children, childIdx, 0xA1);
    if (found >= 0) {
      final child = node.children[found];
      final items = <FileManagement__item_>[];
      for (final n in child.children) {
        items.add(FileManagement__item_.decode(n));
      }
      fileManagementCMD = items;
      childIdx = found + 1;
    }
    return PE_GenericFileManagement._(
      gfm_header: gfm_header,
      fileManagementCMD: fileManagementCMD,
      asn1: node, // Store original node
    );
  }

  static PE_GenericFileManagement decode(dynamic data) {
