  final UInt8? pinAttributes;
  final UInt8? maxNumOfAttemps_retryNumLeft;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const PINConfiguration._({
    this.keyReference,
    this.pinValue,
    this.unblockingPINReference,
    this.pinAttributes,
    this.maxNumOfAttemps_retryNumLeft,
    this.asn1,
  });

  const PINConfiguration({
    PINKeyReferenceValue? keyReference,
    Uint8List? pinValue,
    PUKKeyReferenceValue? unblockingPINReference,
    UInt8? pinAttributes,
    UInt8? maxNumOfAttemps_retryNumLeft,
  }) : this._(
         keyReference: keyReference,
         pinValue: pinValue,
         unblockingPINReference: unblockingPINReference,
         pinAttributes: pinAttributes,
         maxNumOfAttemps_retryNumLeft: maxNumOfAttemps_retryNumLeft,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (keyReference != null) {
      children.add(asn1EncodeRaw(0x80, asn1EncodeInt(keyReference!.value)));
    }
    if (pinValue != null) {
      children.add(asn1EncodeRaw(0x81, pinValue!));
    }
    if (unblockingPINReference != null) {
      children.add(
        asn1EncodeRaw(0x82, asn1EncodeInt(unblockingPINReference!.value)),
      );
    }
    if (pinAttributes != null) {
      children.add(asn1EncodeRaw(0x83, pinAttributes!));
    }
    if (maxNumOfAttemps_retryNumLeft != null) {
      children.add(asn1EncodeRaw(0x84, maxNumOfAttemps_retryNumLeft!));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory PINConfiguration.fromAsn1(Asn1Node node) {
    PINKeyReferenceValue? keyReference;
    Uint8List? pinValue;
    PUKKeyReferenceValue? unblockingPINReference;
    UInt8? pinAttributes;
    UInt8? maxNumOfAttemps_retryNumLeft;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x80);
    if (found >= 0) {
      final child = node.children[found];
      keyReference = PINKeyReferenceValueExt.fromValue(
        asn1DecodeInt(child.value),
      );
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x81);
    if (found >= 0) {
      final child = node.children[found];
      pinValue = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x82);
    if (found >= 0) {
      final child = node.children[found];
      unblockingPINReference = PUKKeyReferenceValueExt.fromValue(
        asn1DecodeInt(child.value),
      );
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x83);
    if (found >= 0) {
      final child = node.children[found];
      pinAttributes = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x84);
    if (found >= 0) {
      final child = node.children[found];
      maxNumOfAttemps_retryNumLeft = child.value;
      childIdx = found + 1;
    }
    return PINConfiguration._(
      keyReference: keyReference,
      pinValue: pinValue,
      unblockingPINReference: unblockingPINReference,
      pinAttributes: pinAttributes,
      maxNumOfAttemps_retryNumLeft: maxNumOfAttemps_retryNumLeft,
