      for (final v in tarList!) {
        items.add(asn1EncodeRaw(0x4, v));
      }
      children.add(asn1EncodeConstructed(0xA0, items));
    }
    if (minimumSecurityLevel != null) {
      children.add(asn1EncodeRaw(0x81, minimumSecurityLevel!));
    }
    if (uiccAccessDomain != null) {
      children.add(asn1EncodeRaw(0x4, uiccAccessDomain!));
