      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA0);
    if (found >= 0) {
      final child = node.children[found];
      final items = <Uint8List>[];
      for (final n in child.children) {
        items.add(n.value);
      }
      tarList = items;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x81);
    if (found >= 0) {
