class PEStatus {
  final PEStatus_status? status;
  final UInt15? identification;
  final UInt8? additional_information;
  final UInt31? offset;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const PEStatus._({
    this.status,
    this.identification,
    this.additional_information,
    this.offset,
    this.asn1,
  });

  const PEStatus({
    PEStatus_status? status,
    UInt15? identification,
    UInt8? additional_information,
    UInt31? offset,
  }) : this._(
         status: status,
         identification: identification,
         additional_information: additional_information,
         offset: offset,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (status != null) {
      children.add(asn1EncodeRaw(0x80, asn1EncodeInt(status!.value)));
    }
    if (identification != null) {
      children.add(asn1EncodeRaw(0x81, identification!));
    }
    if (additional_information != null) {
      children.add(asn1EncodeRaw(0x82, additional_information!));
    }
    if (offset != null) {
      children.add(asn1EncodeRaw(0x83, offset!));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory PEStatus.fromAsn1(Asn1Node node) {
    PEStatus_status? status;
    UInt15? identification;
    UInt8? additional_information;
    UInt31? offset;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x80);
    if (found >= 0) {
      final child = node.children[found];
      status = PEStatus_statusExt.fromValue(asn1DecodeInt(child.value));
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x81);
    if (found >= 0) {
      final child = node.children[found];
      identification = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x82);
    if (found >= 0) {
      final child = node.children[found];
      additional_information = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x83);
    if (found >= 0) {
      final child = node.children[found];
      offset = child.value;
      childIdx = found + 1;
    }
    return PEStatus._(
      status: status,
      identification: identification,
      additional_information: additional_information,
      offset: offset,
      asn1: node, // Store original node
    );
  }

  static PEStatus decode(dynamic data) {
    if (data is Asn1Node) {
      return PEStatus.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return PEStatus.fromAsn1(node);
      }
    }
    return PEStatus();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('PEStatus(');
    final statusVal = status;
    if (statusVal != null) {
      buffer.writeln(
        '  status: ${statusVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final identificationVal = identification;
    if (identificationVal != null) {
      buffer.writeln('  identification: ${asn1Hex(identificationVal)},');
    }
    final additional_informationVal = additional_information;
    if (additional_informationVal != null) {
      buffer.writeln(
        '  additional_information: ${asn1Hex(additional_informationVal)},',
      );
    }
    final offsetVal = offset;
    if (offsetVal != null) {
      buffer.writeln('  offset: ${asn1Hex(offsetVal)},');
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class EUICCResponse {
  final List<PEStatus>? peStatus;
  final Uint8List? profileInstallationAborted;
  final String? statusMessage;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const EUICCResponse._({
    this.peStatus,
    this.profileInstallationAborted,
    this.statusMessage,
    this.asn1,
  });

  const EUICCResponse({
    List<PEStatus>? peStatus,
    Uint8List? profileInstallationAborted,
    String? statusMessage,
  }) : this._(
         peStatus: peStatus,
         profileInstallationAborted: profileInstallationAborted,
         statusMessage: statusMessage,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (peStatus != null) {
      final items = <Uint8List>[];
      for (final v in peStatus!) {
        items.add(v.encode(tag: 0x30));
      }
      children.add(asn1EncodeConstructed(0xA0, items));
    }
    if (profileInstallationAborted != null) {
      children.add(asn1EncodeRaw(0x81, profileInstallationAborted!));
    }
    if (statusMessage != null) {
      children.add(
        asn1EncodeRaw(0x82, Uint8List.fromList(statusMessage!.codeUnits)),
      );
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory EUICCResponse.fromAsn1(Asn1Node node) {
    List<PEStatus>? peStatus;
    Uint8List? profileInstallationAborted;
    String? statusMessage;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0xA0);
    if (found >= 0) {
      final child = node.children[found];
      final items = <PEStatus>[];
      for (final n in child.children) {
        items.add(PEStatus.decode(n));
      }
      peStatus = items;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x81);
    if (found >= 0) {
      final child = node.children[found];
      profileInstallationAborted = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x82);
    if (found >= 0) {
      final child = node.children[found];
      statusMessage = String.fromCharCodes(child.value);
      childIdx = found + 1;
    }
    return EUICCResponse._(
      peStatus: peStatus,
      profileInstallationAborted: profileInstallationAborted,
      statusMessage: statusMessage,
      asn1: node, // Store original node
    );
  }

  static EUICCResponse decode(dynamic data) {
    if (data is Asn1Node) {
      return EUICCResponse.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return EUICCResponse.fromAsn1(node);
      }
    }
    return EUICCResponse();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('EUICCResponse(');
    final peStatusVal = peStatus;
    if (peStatusVal != null) {
      buffer.writeln(
        '  peStatus: [${peStatusVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    final profileInstallationAbortedVal = profileInstallationAborted;
    if (profileInstallationAbortedVal != null) {
      buffer.writeln(
        '  profileInstallationAborted: ${asn1Hex(profileInstallationAbortedVal)},',
      );
    }
    final statusMessageVal = statusMessage;
    if (statusMessageVal != null) {
      buffer.writeln(
        '  statusMessage: ${statusMessageVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

