class DeviceInfo {
  final Octet4? tac;
  final DeviceCapabilities? deviceCapabilities;
  final Octet8? imei;
  final List<Uint8List>? preferredLanguages;
  final Uint8List? deviceTestMode;
  final LpaRspCapability? lpaRspCapability;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const DeviceInfo._({
    this.tac,
    this.deviceCapabilities,
    this.imei,
    this.preferredLanguages,
    this.deviceTestMode,
    this.lpaRspCapability,
    this.asn1,
  });

  const DeviceInfo({
    Octet4? tac,
    DeviceCapabilities? deviceCapabilities,
    Octet8? imei,
    List<Uint8List>? preferredLanguages,
    Uint8List? deviceTestMode,
    LpaRspCapability? lpaRspCapability,
  }) : this._(
         tac: tac,
         deviceCapabilities: deviceCapabilities,
         imei: imei,
         preferredLanguages: preferredLanguages,
         deviceTestMode: deviceTestMode,
         lpaRspCapability: lpaRspCapability,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (tac != null) {
      children.add(asn1EncodeRaw(0x80, tac!));
    }
    if (deviceCapabilities != null) {
      children.add(deviceCapabilities!.encode(tag: 0xA1));
    }
    if (imei != null) {
      children.add(asn1EncodeRaw(0x82, imei!));
    }
    if (preferredLanguages != null) {
      final items = <Uint8List>[];
      for (final v in preferredLanguages!) {
        items.add(asn1EncodeRaw(0xC, v));
      }
      children.add(asn1EncodeConstructed(0xA3, items));
    }
    if (deviceTestMode != null) {
      children.add(asn1EncodeRaw(0x84, deviceTestMode!));
    }
    if (lpaRspCapability != null) {
      children.add(
        asn1EncodeRaw(0x85, asn1EncodeBits(lpaRspCapability!.value)),
      );
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory DeviceInfo.fromAsn1(Asn1Node node) {
    Octet4? tac;
    DeviceCapabilities? deviceCapabilities;
    Octet8? imei;
    List<Uint8List>? preferredLanguages;
    Uint8List? deviceTestMode;
    LpaRspCapability? lpaRspCapability;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x80);
    if (found >= 0) {
      final child = node.children[found];
      tac = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA1);
    if (found >= 0) {
      final child = node.children[found];
      deviceCapabilities = DeviceCapabilities.decode(child);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x82);
    if (found >= 0) {
      final child = node.children[found];
      imei = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA3);
    if (found >= 0) {
      final child = node.children[found];
      final items = <Uint8List>[];
      for (final n in child.children) {
        items.add(n.value);
      }
      preferredLanguages = items;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x84);
    if (found >= 0) {
      final child = node.children[found];
      deviceTestMode = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x85);
    if (found >= 0) {
      final child = node.children[found];
      lpaRspCapability = LpaRspCapability(asn1DecodeBits(child.value));
      childIdx = found + 1;
    }
    return DeviceInfo._(
      tac: tac,
      deviceCapabilities: deviceCapabilities,
      imei: imei,
      preferredLanguages: preferredLanguages,
      deviceTestMode: deviceTestMode,
      lpaRspCapability: lpaRspCapability,
      asn1: node, // Store original node
    );
