    if (data is Asn1Node) {
      return DeviceInfo.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return DeviceInfo.fromAsn1(node);
      }
    }
    return DeviceInfo();
