    VersionType? lowestSvn;
    List<SubjectKeyIdentifier>? euiccCiPKIdListForVerification;
    List<SubjectKeyIdentifier>? euiccCiPKIdListForSigning;
    List<SubjectKeyIdentifier>? euiccCiPKIdListForSigningV3;
