    VersionType? highestSvn;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x82);
    if (found >= 0) {
      final child = node.children[found];
      lowestSvn = child.value;
      childIdx = found + 1;
