    found = asn1SeekTag(node.children, childIdx, 0xA9);
    if (found >= 0) {
      final child = node.children[found];
      final items = <SubjectKeyIdentifier>[];
      for (final n in child.children) {
        items.add(n.value);
      }
      euiccCiPKIdListForVerification = items;
      childIdx = found + 1;
