class CertificationDataObject {
  final String? platformLabel;
  final String? discoveryBaseURL;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const CertificationDataObject._({
    this.platformLabel,
    this.discoveryBaseURL,
    this.asn1,
  });

  const CertificationDataObject({
    String? platformLabel,
    String? discoveryBaseURL,
  }) : this._(
         platformLabel: platformLabel,
         discoveryBaseURL: discoveryBaseURL,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (platformLabel != null) {
      children.add(
        asn1EncodeRaw(0x80, Uint8List.fromList(platformLabel!.codeUnits)),
      );
    }
    if (discoveryBaseURL != null) {
      children.add(
        asn1EncodeRaw(0x81, Uint8List.fromList(discoveryBaseURL!.codeUnits)),
      );
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory CertificationDataObject.fromAsn1(Asn1Node node) {
    String? platformLabel;
    String? discoveryBaseURL;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x80);
    if (found >= 0) {
      final child = node.children[found];
      platformLabel = String.fromCharCodes(child.value);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x81);
    if (found >= 0) {
      final child = node.children[found];
      discoveryBaseURL = String.fromCharCodes(child.value);
      childIdx = found + 1;
    }
    return CertificationDataObject._(
      platformLabel: platformLabel,
      discoveryBaseURL: discoveryBaseURL,
      asn1: node, // Store original node
    );
  }

  static CertificationDataObject decode(dynamic data) {
    if (data is Asn1Node) {
      return CertificationDataObject.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return CertificationDataObject.fromAsn1(node);
      }
    }
    return CertificationDataObject();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('CertificationDataObject(');
    final platformLabelVal = platformLabel;
    if (platformLabelVal != null) {
      buffer.writeln(
        '  platformLabel: ${platformLabelVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final discoveryBaseURLVal = discoveryBaseURL;
    if (discoveryBaseURLVal != null) {
      buffer.writeln(
        '  discoveryBaseURL: ${discoveryBaseURLVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    buffer.write(')');
