    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (serviceProviderName != null) {
      children.add(
        asn1EncodeRaw(0x91, Uint8List.fromList(serviceProviderName!.codeUnits)),
      );
    }
    if (profileName != null) {
      children.add(
        asn1EncodeRaw(0x92, Uint8List.fromList(profileName!.codeUnits)),
      );
    }
    if (iconType != null) {
      children.add(asn1EncodeRaw(0x93, asn1EncodeInt(iconType!.value)));
