    this.smdpSign,
    this.asn1,
  });

  const InitialiseSecureChannelRequest({
    RemoteOpId? remoteOpId,
    TransactionId? transactionId,
    ControlRefTemplate? controlRefTemplate,
    Uint8List? smdpOtpk,
    Uint8List? smdpSign,
  }) : this._(
         remoteOpId: remoteOpId,
         transactionId: transactionId,
         controlRefTemplate: controlRefTemplate,
