    if (remoteOpId != null) {
      children.add(asn1EncodeRaw(0x82, asn1EncodeInt(remoteOpId!.value)));
    }
    if (transactionId != null) {
      children.add(asn1EncodeRaw(0x80, transactionId!));
    }
    if (controlRefTemplate != null) {
      children.add(controlRefTemplate!.encode(tag: 0xA6));
    }
    if (smdpOtpk != null) {
      children.add(asn1EncodeRaw(0x5F49, smdpOtpk!));
    }
    if (smdpSign != null) {
      children.add(asn1EncodeRaw(0x5F37, smdpSign!));
    }
    return asn1EncodeConstructed(tag ?? 0xBF23, children);
  }

  factory InitialiseSecureChannelRequest.fromAsn1(Asn1Node node) {
    RemoteOpId? remoteOpId;
    TransactionId? transactionId;
    ControlRefTemplate? controlRefTemplate;
    Uint8List? smdpOtpk;
    Uint8List? smdpSign;
