    int found;
    found = asn1SeekTag(node.children, childIdx, 0x82);
    if (found >= 0) {
      final child = node.children[found];
      remoteOpId = RemoteOpIdExt.fromValue(asn1DecodeInt(child.value));
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x80);
    if (found >= 0) {
      final child = node.children[found];
      transactionId = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA6);
    if (found >= 0) {
      final child = node.children[found];
      controlRefTemplate = ControlRefTemplate.decode(child);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x5F49);
    if (found >= 0) {
      final child = node.children[found];
      smdpOtpk = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x5F37);
    if (found >= 0) {
      final child = node.children[found];
      smdpSign = child.value;
      childIdx = found + 1;
    }
    return InitialiseSecureChannelRequest._(
      remoteOpId: remoteOpId,
      transactionId: transactionId,
      controlRefTemplate: controlRefTemplate,
      smdpOtpk: smdpOtpk,
      smdpSign: smdpSign,
      asn1: node, // Store original node
