class AuthenticateServerRequest {
  final ServerSigned1? serverSigned1;
  final Uint8List? serverSignature1;
  final SubjectKeyIdentifier? euiccCiPKIdToBeUsed;
  final Certificate? serverCertificate;
  final CtxParams1? ctxParams1;
  final CertificateChain? otherCertsInChain;
  final List<CertificateList>? crlList;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const AuthenticateServerRequest._({
    this.serverSigned1,
    this.serverSignature1,
    this.euiccCiPKIdToBeUsed,
    this.serverCertificate,
    this.ctxParams1,
    this.otherCertsInChain,
    this.crlList,
    this.asn1,
  });

  const AuthenticateServerRequest({
    ServerSigned1? serverSigned1,
    Uint8List? serverSignature1,
    SubjectKeyIdentifier? euiccCiPKIdToBeUsed,
    Certificate? serverCertificate,
    CtxParams1? ctxParams1,
    CertificateChain? otherCertsInChain,
    List<CertificateList>? crlList,
  }) : this._(
         serverSigned1: serverSigned1,
         serverSignature1: serverSignature1,
         euiccCiPKIdToBeUsed: euiccCiPKIdToBeUsed,
         serverCertificate: serverCertificate,
         ctxParams1: ctxParams1,
         otherCertsInChain: otherCertsInChain,
         crlList: crlList,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (serverSigned1 != null) {
      children.add(serverSigned1!.encode(tag: 0x30));
    }
    if (serverSignature1 != null) {
      children.add(asn1EncodeRaw(0x5F37, serverSignature1!));
    }
    if (euiccCiPKIdToBeUsed != null) {
      children.add(asn1EncodeRaw(0x4, euiccCiPKIdToBeUsed!));
    }
    if (serverCertificate != null) {
      children.add(serverCertificate!.encode(tag: 0x30));
    }
    if (ctxParams1 != null) {
      children.add(ctxParams1!.encode());
    }
    if (otherCertsInChain != null) {
      final items = <Uint8List>[];
      for (final v in otherCertsInChain!) {
        items.add(v.encode(tag: 0x30));
      }
      children.add(asn1EncodeConstructed(0xA1, items));
    }
    if (crlList != null) {
      final items = <Uint8List>[];
      for (final v in crlList!) {
        items.add(v.encode(tag: 0x30));
      }
      children.add(asn1EncodeConstructed(0xA2, items));
    }
    return asn1EncodeConstructed(tag ?? 0xBF38, children);
  }

  factory AuthenticateServerRequest.fromAsn1(Asn1Node node) {
    ServerSigned1? serverSigned1;
    Uint8List? serverSignature1;
    SubjectKeyIdentifier? euiccCiPKIdToBeUsed;
    Certificate? serverCertificate;
    CtxParams1? ctxParams1;
    CertificateChain? otherCertsInChain;
    List<CertificateList>? crlList;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x30);
    if (found >= 0) {
      final child = node.children[found];
      serverSigned1 = ServerSigned1.decode(child);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x5F37);
    if (found >= 0) {
      final child = node.children[found];
      serverSignature1 = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x4);
    if (found >= 0) {
      final child = node.children[found];
      euiccCiPKIdToBeUsed = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x30);
    if (found >= 0) {
      final child = node.children[found];
      serverCertificate = Certificate.decode(child);
      childIdx = found + 1;
    }
    if (childIdx < node.children.length) {
      final child = node.children[childIdx];
      ctxParams1 = CtxParams1.decode(child);
      childIdx++;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA1);
    if (found >= 0) {
      final child = node.children[found];
      final items = <Certificate>[];
      for (final n in child.children) {
        items.add(Certificate.decode(n));
      }
      otherCertsInChain = items;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA2);
    if (found >= 0) {
      final child = node.children[found];
      final items = <CertificateList>[];
      for (final n in child.children) {
        items.add(CertificateList.decode(n));
      }
      crlList = items;
      childIdx = found + 1;
    }
    return AuthenticateServerRequest._(
      serverSigned1: serverSigned1,
      serverSignature1: serverSignature1,
      euiccCiPKIdToBeUsed: euiccCiPKIdToBeUsed,
      serverCertificate: serverCertificate,
      ctxParams1: ctxParams1,
      otherCertsInChain: otherCertsInChain,
      crlList: crlList,
      asn1: node, // Store original node
    );
  }

  static AuthenticateServerRequest decode(dynamic data) {
    if (data is Asn1Node) {
      return AuthenticateServerRequest.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return AuthenticateServerRequest.fromAsn1(node);
      }
    }
    return AuthenticateServerRequest();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('AuthenticateServerRequest(');
    final serverSigned1Val = serverSigned1;
    if (serverSigned1Val != null) {
      buffer.writeln(
        '  serverSigned1: ${serverSigned1Val.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final serverSignature1Val = serverSignature1;
    if (serverSignature1Val != null) {
      buffer.writeln('  serverSignature1: ${asn1Hex(serverSignature1Val)},');
    }
    final euiccCiPKIdToBeUsedVal = euiccCiPKIdToBeUsed;
    if (euiccCiPKIdToBeUsedVal != null) {
      buffer.writeln(
        '  euiccCiPKIdToBeUsed: ${asn1Hex(euiccCiPKIdToBeUsedVal)},',
      );
    }
    final serverCertificateVal = serverCertificate;
    if (serverCertificateVal != null) {
      buffer.writeln(
        '  serverCertificate: ${serverCertificateVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final ctxParams1Val = ctxParams1;
    if (ctxParams1Val != null) {
      buffer.writeln(
        '  ctxParams1: ${ctxParams1Val.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final otherCertsInChainVal = otherCertsInChain;
    if (otherCertsInChainVal != null) {
      buffer.writeln(
        '  otherCertsInChain: [${otherCertsInChainVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    final crlListVal = crlList;
    if (crlListVal != null) {
      buffer.writeln(
        '  crlList: [${crlListVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class ServerSigned1 {
  final TransactionId? transactionId;
  final Octet16? euiccChallenge;
  final String? serverAddress;
  final Octet16? serverChallenge;
  final SessionContext? sessionContext;
  final ServerRspCapability? serverRspCapability;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const ServerSigned1._({
    this.transactionId,
    this.euiccChallenge,
    this.serverAddress,
    this.serverChallenge,
    this.sessionContext,
    this.serverRspCapability,
    this.asn1,
  });

  const ServerSigned1({
    TransactionId? transactionId,
    Octet16? euiccChallenge,
    String? serverAddress,
    Octet16? serverChallenge,
    SessionContext? sessionContext,
    ServerRspCapability? serverRspCapability,
  }) : this._(
         transactionId: transactionId,
         euiccChallenge: euiccChallenge,
         serverAddress: serverAddress,
         serverChallenge: serverChallenge,
         sessionContext: sessionContext,
         serverRspCapability: serverRspCapability,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (transactionId != null) {
      children.add(asn1EncodeRaw(0x80, transactionId!));
    }
    if (euiccChallenge != null) {
      children.add(asn1EncodeRaw(0x81, euiccChallenge!));
    }
    if (serverAddress != null) {
      children.add(
        asn1EncodeRaw(0x83, Uint8List.fromList(serverAddress!.codeUnits)),
      );
    }
    if (serverChallenge != null) {
      children.add(asn1EncodeRaw(0x84, serverChallenge!));
    }
    if (sessionContext != null) {
      children.add(sessionContext!.encode(tag: 0xA5));
    }
    if (serverRspCapability != null) {
      children.add(
        asn1EncodeRaw(0x86, asn1EncodeBits(serverRspCapability!.value)),
      );
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory ServerSigned1.fromAsn1(Asn1Node node) {
    TransactionId? transactionId;
    Octet16? euiccChallenge;
    String? serverAddress;
    Octet16? serverChallenge;
    SessionContext? sessionContext;
    ServerRspCapability? serverRspCapability;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x80);
    if (found >= 0) {
      final child = node.children[found];
      transactionId = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x81);
    if (found >= 0) {
      final child = node.children[found];
      euiccChallenge = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x83);
    if (found >= 0) {
      final child = node.children[found];
      serverAddress = String.fromCharCodes(child.value);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x84);
    if (found >= 0) {
      final child = node.children[found];
      serverChallenge = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA5);
    if (found >= 0) {
      final child = node.children[found];
      sessionContext = SessionContext.decode(child);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x86);
    if (found >= 0) {
      final child = node.children[found];
      serverRspCapability = ServerRspCapability(asn1DecodeBits(child.value));
      childIdx = found + 1;
    }
    return ServerSigned1._(
      transactionId: transactionId,
      euiccChallenge: euiccChallenge,
      serverAddress: serverAddress,
      serverChallenge: serverChallenge,
      sessionContext: sessionContext,
      serverRspCapability: serverRspCapability,
      asn1: node, // Store original node
    );
  }

  static ServerSigned1 decode(dynamic data) {
    if (data is Asn1Node) {
      return ServerSigned1.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return ServerSigned1.fromAsn1(node);
      }
    }
    return ServerSigned1();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('ServerSigned1(');
    final transactionIdVal = transactionId;
    if (transactionIdVal != null) {
      buffer.writeln('  transactionId: ${asn1Hex(transactionIdVal)},');
    }
    final euiccChallengeVal = euiccChallenge;
    if (euiccChallengeVal != null) {
      buffer.writeln('  euiccChallenge: ${asn1Hex(euiccChallengeVal)},');
    }
    final serverAddressVal = serverAddress;
    if (serverAddressVal != null) {
      buffer.writeln(
        '  serverAddress: ${serverAddressVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final serverChallengeVal = serverChallenge;
    if (serverChallengeVal != null) {
      buffer.writeln('  serverChallenge: ${asn1Hex(serverChallengeVal)},');
    }
    final sessionContextVal = sessionContext;
    if (sessionContextVal != null) {
      buffer.writeln(
        '  sessionContext: ${sessionContextVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final serverRspCapabilityVal = serverRspCapability;
    if (serverRspCapabilityVal != null) {
      buffer.writeln(
        '  serverRspCapability: ${serverRspCapabilityVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class CtxParams1 {
  final CtxParamsForCommonAuthentication? ctxParamsForCommonAuthentication;
  final CtxParamsForDeviceChange? ctxParamsForDeviceChange;
