class CtxParamsForCommonAuthentication {
  final String? matchingId;
  final DeviceInfo? deviceInfo;
  final OperationType? operationType;
  final Iccid? iccid;
  final MatchingIdSource? matchingIdSource;
  final VendorSpecificExtension? vendorSpecificExtension;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const CtxParamsForCommonAuthentication._({
    this.matchingId,
    this.deviceInfo,
    this.operationType,
    this.iccid,
    this.matchingIdSource,
    this.vendorSpecificExtension,
    this.asn1,
  });

  const CtxParamsForCommonAuthentication({
    String? matchingId,
    DeviceInfo? deviceInfo,
    OperationType? operationType,
    Iccid? iccid,
    MatchingIdSource? matchingIdSource,
    VendorSpecificExtension? vendorSpecificExtension,
  }) : this._(
         matchingId: matchingId,
         deviceInfo: deviceInfo,
         operationType: operationType,
         iccid: iccid,
         matchingIdSource: matchingIdSource,
         vendorSpecificExtension: vendorSpecificExtension,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (matchingId != null) {
      children.add(
        asn1EncodeRaw(0x80, Uint8List.fromList(matchingId!.codeUnits)),
      );
    }
    if (deviceInfo != null) {
      children.add(deviceInfo!.encode(tag: 0xA1));
    }
    if (operationType != null) {
      children.add(asn1EncodeRaw(0x82, asn1EncodeBits(operationType!.value)));
    }
    if (iccid != null) {
      children.add(asn1EncodeRaw(0x5A, iccid!));
    }
    if (matchingIdSource != null) {
      children.add(asn1EncodeConstructed(0xA3, [matchingIdSource!.encode()]));
    }
    if (vendorSpecificExtension != null) {
      final items = <Uint8List>[];
      for (final v in vendorSpecificExtension!) {
        items.add(v.encode(tag: 0x30));
      }
      children.add(asn1EncodeConstructed(0xA4, items));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory CtxParamsForCommonAuthentication.fromAsn1(Asn1Node node) {
    String? matchingId;
    DeviceInfo? deviceInfo;
    OperationType? operationType;
    Iccid? iccid;
    MatchingIdSource? matchingIdSource;
    VendorSpecificExtension? vendorSpecificExtension;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x80);
    if (found >= 0) {
      final child = node.children[found];
      matchingId = String.fromCharCodes(child.value);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA1);
    if (found >= 0) {
      final child = node.children[found];
      deviceInfo = DeviceInfo.decode(child);
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x82);
    if (found >= 0) {
      final child = node.children[found];
      operationType = OperationType(asn1DecodeBits(child.value));
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x5A);
    if (found >= 0) {
      final child = node.children[found];
      iccid = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA3);
    if (found >= 0) {
      final child = node.children[found];
      matchingIdSource = MatchingIdSource.decode(asn1Explicit(child));
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0xA4);
    if (found >= 0) {
      final child = node.children[found];
      final items = <VendorSpecificExtension__item_>[];
      for (final n in child.children) {
        items.add(VendorSpecificExtension__item_.decode(n));
      }
      vendorSpecificExtension = items;
      childIdx = found + 1;
