class SetNicknameRequest {
  final Iccid? iccid;
  final String? profileNickname;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const SetNicknameRequest._({this.iccid, this.profileNickname, this.asn1});

  const SetNicknameRequest({Iccid? iccid, String? profileNickname})
    : this._(iccid: iccid, profileNickname: profileNickname, asn1: null);

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (iccid != null) {
      children.add(asn1EncodeRaw(0x5A, iccid!));
    }
    if (profileNickname != null) {
      children.add(
        asn1EncodeRaw(0x90, Uint8List.fromList(profileNickname!.codeUnits)),
      );
    }
    return asn1EncodeConstructed(tag ?? 0xBF29, children);
  }

  factory SetNicknameRequest.fromAsn1(Asn1Node node) {
    Iccid? iccid;
    String? profileNickname;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x5A);
    if (found >= 0) {
      final child = node.children[found];
      iccid = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x90);
    if (found >= 0) {
      final child = node.children[found];
      profileNickname = String.fromCharCodes(child.value);
      childIdx = found + 1;
    }
    return SetNicknameRequest._(
      iccid: iccid,
      profileNickname: profileNickname,
      asn1: node, // Store original node
    );
  }

  static SetNicknameRequest decode(dynamic data) {
    if (data is Asn1Node) {
      return SetNicknameRequest.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return SetNicknameRequest.fromAsn1(node);
      }
    }
    return SetNicknameRequest();
  }

  @override
