class GetRatResponse {
  final RulesAuthorisationTable? rat;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const GetRatResponse._({this.rat, this.asn1});

  const GetRatResponse({RulesAuthorisationTable? rat})
    : this._(rat: rat, asn1: null);

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (rat != null) {
      final items = <Uint8List>[];
      for (final v in rat!) {
        items.add(v.encode(tag: 0x30));
      }
      children.add(asn1EncodeConstructed(0xA0, items));
    }
    return asn1EncodeConstructed(tag ?? 0xBF43, children);
  }

  factory GetRatResponse.fromAsn1(Asn1Node node) {
    RulesAuthorisationTable? rat;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0xA0);
    if (found >= 0) {
      final child = node.children[found];
      final items = <ProfilePolicyAuthorisationRule>[];
      for (final n in child.children) {
        items.add(ProfilePolicyAuthorisationRule.decode(n));
      }
      rat = items;
      childIdx = found + 1;
    }
    return GetRatResponse._(
      rat: rat,
      asn1: node, // Store original node
    );
  }

  static GetRatResponse decode(dynamic data) {
    if (data is Asn1Node) {
      return GetRatResponse.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return GetRatResponse.fromAsn1(node);
      }
    }
    return GetRatResponse();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('GetRatResponse(');
    final ratVal = rat;
    if (ratVal != null) {
      buffer.writeln(
        '  rat: [${ratVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class ProfilePolicyAuthorisationRule {
  final PprIds? pprIds;
  final List<OperatorId>? allowedOperators;
  final int? pprFlags;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const ProfilePolicyAuthorisationRule._({
    this.pprIds,
    this.allowedOperators,
    this.pprFlags,
    this.asn1,
  });

  const ProfilePolicyAuthorisationRule({
    PprIds? pprIds,
    List<OperatorId>? allowedOperators,
    int? pprFlags,
  }) : this._(
         pprIds: pprIds,
         allowedOperators: allowedOperators,
         pprFlags: pprFlags,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (pprIds != null) {
      children.add(asn1EncodeRaw(0x80, asn1EncodeBits(pprIds!.value)));
    }
    if (allowedOperators != null) {
      final items = <Uint8List>[];
      for (final v in allowedOperators!) {
        items.add(v.encode(tag: 0x30));
      }
      children.add(asn1EncodeConstructed(0xA1, items));
    }
    if (pprFlags != null) {
      children.add(asn1EncodeRaw(0x82, asn1EncodeBits(pprFlags!)));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory ProfilePolicyAuthorisationRule.fromAsn1(Asn1Node node) {
    PprIds? pprIds;
    List<OperatorId>? allowedOperators;
    int? pprFlags;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x80);
