      allowedOperators = items;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x82);
    if (found >= 0) {
      final child = node.children[found];
      pprFlags = asn1DecodeBits(child.value);
      childIdx = found + 1;
    }
    return ProfilePolicyAuthorisationRule._(
      pprIds: pprIds,
      allowedOperators: allowedOperators,
      pprFlags: pprFlags,
