    String? activationCodeForProfileRecovery;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x80);
    if (found >= 0) {
      final child = node.children[found];
      transactionId = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x1);
    if (found >= 0) {
      final child = node.children[found];
      ccRequiredFlag = child.value.isNotEmpty && child.value.first != 0;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x81);
    if (found >= 0) {
      final child = node.children[found];
      activationCodeForProfileRecovery = String.fromCharCodes(child.value);
      childIdx = found + 1;
    }
    return SmdpSigned4._(
      transactionId: transactionId,
      ccRequiredFlag: ccRequiredFlag,
      activationCodeForProfileRecovery: activationCodeForProfileRecovery,
      asn1: node, // Store original node
    );
  }

  static SmdpSigned4 decode(dynamic data) {
    if (data is Asn1Node) {
      return SmdpSigned4.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return SmdpSigned4.fromAsn1(node);
      }
    }
    return SmdpSigned4();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('SmdpSigned4(');
    final transactionIdVal = transactionId;
    if (transactionIdVal != null) {
      buffer.writeln('  transactionId: ${asn1Hex(transactionIdVal)},');
    }
    final ccRequiredFlagVal = ccRequiredFlag;
    if (ccRequiredFlagVal != null) {
      buffer.writeln(
        '  ccRequiredFlag: ${ccRequiredFlagVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    final activationCodeForProfileRecoveryVal =
        activationCodeForProfileRecovery;
    if (activationCodeForProfileRecoveryVal != null) {
      buffer.writeln(
        '  activationCodeForProfileRecovery: ${activationCodeForProfileRecoveryVal.toString().replaceAll("\n", "\n  ")},',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

