class EUICCSigned3 {
  final TransactionId? transactionId;
  final Uint8List? eacEuiccOtpk;
  final Octet32? hashCc;
  final VendorSpecificExtension? additionalInformation;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const EUICCSigned3._({
    this.transactionId,
    this.eacEuiccOtpk,
    this.hashCc,
    this.additionalInformation,
    this.asn1,
  });

  const EUICCSigned3({
    TransactionId? transactionId,
    Uint8List? eacEuiccOtpk,
    Octet32? hashCc,
    VendorSpecificExtension? additionalInformation,
  }) : this._(
         transactionId: transactionId,
         eacEuiccOtpk: eacEuiccOtpk,
         hashCc: hashCc,
         additionalInformation: additionalInformation,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    if (transactionId != null) {
      children.add(asn1EncodeRaw(0x80, transactionId!));
    }
    if (eacEuiccOtpk != null) {
      children.add(asn1EncodeRaw(0x5F49, eacEuiccOtpk!));
    }
    if (hashCc != null) {
      children.add(asn1EncodeRaw(0x4, hashCc!));
    }
    if (additionalInformation != null) {
      final items = <Uint8List>[];
      for (final v in additionalInformation!) {
        items.add(v.encode(tag: 0x30));
      }
      children.add(asn1EncodeConstructed(0x30, items));
    }
    return asn1EncodeConstructed(tag ?? 0x30, children);
  }

  factory EUICCSigned3.fromAsn1(Asn1Node node) {
    TransactionId? transactionId;
    Uint8List? eacEuiccOtpk;
    Octet32? hashCc;
    VendorSpecificExtension? additionalInformation;
    int childIdx = 0;
    int found;
    found = asn1SeekTag(node.children, childIdx, 0x80);
    if (found >= 0) {
      final child = node.children[found];
      transactionId = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x5F49);
    if (found >= 0) {
      final child = node.children[found];
      eacEuiccOtpk = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x4);
    if (found >= 0) {
      final child = node.children[found];
      hashCc = child.value;
      childIdx = found + 1;
    }
    found = asn1SeekTag(node.children, childIdx, 0x30);
    if (found >= 0) {
      final child = node.children[found];
      final items = <VendorSpecificExtension__item_>[];
      for (final n in child.children) {
        items.add(VendorSpecificExtension__item_.decode(n));
      }
      additionalInformation = items;
      childIdx = found + 1;
    }
    return EUICCSigned3._(
      transactionId: transactionId,
      eacEuiccOtpk: eacEuiccOtpk,
      hashCc: hashCc,
      additionalInformation: additionalInformation,
      asn1: node, // Store original node
    );
  }

  static EUICCSigned3 decode(dynamic data) {
    if (data is Asn1Node) {
      return EUICCSigned3.fromAsn1(data);
    }
    if (data is Uint8List) {
      final node = Asn1Reader(data).readNext();
      if (node != null) {
        return EUICCSigned3.fromAsn1(node);
      }
    }
    return EUICCSigned3();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('EUICCSigned3(');
    final transactionIdVal = transactionId;
    if (transactionIdVal != null) {
      buffer.writeln('  transactionId: ${asn1Hex(transactionIdVal)},');
    }
    final eacEuiccOtpkVal = eacEuiccOtpk;
    if (eacEuiccOtpkVal != null) {
      buffer.writeln('  eacEuiccOtpk: ${asn1Hex(eacEuiccOtpkVal)},');
    }
    final hashCcVal = hashCc;
    if (hashCcVal != null) {
      buffer.writeln('  hashCc: ${asn1Hex(hashCcVal)},');
    }
    final additionalInformationVal = additionalInformation;
    if (additionalInformationVal != null) {
      buffer.writeln(
        '  additionalInformation: [${additionalInformationVal.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
      );
    }
    buffer.write(')');
    return buffer.toString();
  }
}

