      children.add(startDownload!.encode(tag: 0xA0));
    }
    if (confirmDownload != null) {
      children.add(confirmDownload!.encode(tag: 0xA1));
    }
    if (listProfiles != null) {
      children.add(asn1EncodeRaw(0x82, listProfiles!));
    }
    if (enableProfile != null) {
      children.add(enableProfile!.encode(tag: 0xA3));
    }
