      children.add(
        asn1EncodeRaw(
          0x87,
          Uint8List.fromList(changeConfirmationPin!.codeUnits),
        ),
      );
    }
    if (setRpmAllow != null) {
      children.add(
        asn1EncodeRaw(0x88, Uint8List.fromList([setRpmAllow! ? 0xFF : 0x00])),
      );
    }
    if (pollRpmPackage != null) {
      children.add(pollRpmPackage!.encode(tag: 0xA9));
